<template>
    <el-dialog
      :title="titleDialog"
      :visible="showDialog"
      :close-on-click-modal="false"
      :close-on-press-escape="false"
      @close="handleCloseDialog"
      @open="onOpen">
        <form autocomplete="off" @submit.prevent="submit">
            <div class="form-body">
                <div class="row">
                  <div class="col-md-12">
                    <div :class="{'has-danger': errors.empresa_id}"
                         class="form-group">
                      <label class="control-label">
                        Empresa
                      </label>
                      <el-select
                        v-model="form.empresa_id"
                        clearable
                        filterable
                        placeholder="Ingrese el nombre de la empresa para buscar"
                        remote
                        :remote-method="getEmpresas"
                        :loading="loading"
                        :automatic-dropdown="false"
                        @focus="handleFocus"
                      >
                        <el-option
                          v-for="option in list_empresas"
                          :key="option.id"
                          :label="option.razon_social"
                          :value="option.id">
                        </el-option>

                        <div slot="empty" class="text-center p-2">
                          <template v-if="loading">
                            Cargando...
                          </template>
                          <template v-else>
                            {{ list_empresas.length === 0 ? 'Ingrese al menos 3 caracteres para buscar' : 'No se encontraron resultados' }}
                          </template>
                        </div>
                      </el-select>
                      <small v-if="errors.empresa_id"
                             class="form-control-feedback"
                             v-text="errors.empresa_id[0]"></small>
                    </div>
                  </div>
                </div>
                <div class="row">
                    <div class="col-md-6">
                        <div class="form-group" :class="{'has-danger': errors.nombres}">
                            <label class="control-label">Nombres</label>
                            <el-input v-model="form.nombres"></el-input>
                            <small class="form-control-feedback" v-if="errors.nombres" v-text="errors.nombres[0]"></small>
                        </div>
                    </div>
                    <div class="col-md-6">
                      <div class="form-group" :class="{'has-danger': errors.apellidos}">
                        <label class="control-label">Apellidos</label>
                        <el-input v-model="form.apellidos"></el-input>
                        <small class="form-control-feedback" v-if="errors.apellidos" v-text="errors.apellidos[0]"></small>
                      </div>
                    </div>
                </div>
                <div class="row">
                  <div class="col-md-6">
                    <div class="form-group" :class="{'has-danger': errors.origen}">
                      <label class="control-label">Origen</label>
                      <el-input v-model="form.origen"></el-input>
                      <small class="form-control-feedback" v-if="errors.origen" v-text="errors.origen[0]"></small>
                    </div>
                  </div>
                  <div class="col-md-6">
                    <div class="form-group" :class="{'has-danger': errors.tipo_contacto}">
                      <label class="control-label">Tipo de Contacto</label>
                      <el-input v-model="form.tipo_contacto"></el-input>
                      <small class="form-control-feedback" v-if="errors.tipo_contacto" v-text="errors.tipo_contacto[0]"></small>
                    </div>
                  </div>
                </div>
                <div class="row">
                  <div class="col-md-6">
                    <div class="form-group" :class="{'has-danger': errors.fecha_cumpleanos}">
                      <label class="control-label">Fecha Cumpleaños</label>
                      <el-date-picker v-model="form.fecha_cumpleanos" type="date" value-format="yyyy-MM-dd" format="dd-MM-yyyy" :clearable="false"></el-date-picker>
                      <small class="form-control-feedback" v-if="errors.fecha_cumpleanos" v-text="errors.fecha_cumpleanos[0]"></small>
                    </div>
                  </div>
                  <div class="col-md-6">
                    <div class="form-group" :class="{'has-danger': errors.direccion}">
                      <label class="control-label">Direccion</label>
                      <el-input v-model="form.direccion"></el-input>
                      <small class="form-control-feedback" v-if="errors.direccion" v-text="errors.direccion[0]"></small>
                    </div>
                  </div>
                </div>

                <div class="row">
                  <div class="col-md-4">
                    <div class="form-group" :class="{'has-danger': errors.cargo}">
                      <label class="control-label">Cargo</label>
                      <el-input v-model="form.cargo"></el-input>
                      <small class="form-control-feedback" v-if="errors.cargo" v-text="errors.cargo[0]"></small>
                    </div>
                  </div>
                  <div class="col-md-4">
                    <div class="form-group" :class="{'has-danger': errors.celular}">
                      <label class="control-label">Celular</label>
                      <el-input v-model="form.celular"></el-input>
                      <small class="form-control-feedback" v-if="errors.celular" v-text="errors.celular[0]"></small>
                    </div>
                  </div>
                  <div class="col-md-4">
                    <div :class="{'has-danger': errors.estado}"
                         class="form-group">
                      <label class="control-label">
                        Estado
                      </label>
                      <el-select v-model="form.estado"
                                 clearable
                                 filterable>
                        <el-option v-for="option in list_estados_interno"
                                   :key="option.id"
                                   :label="option.name"
                                   :value="option.id"></el-option>
                      </el-select>
                      <small v-if="errors.estado"
                             class="form-control-feedback"
                             v-text="errors.estado[0]"></small>
                    </div>
                  </div>

                </div>

                <div class="row">
                  <div class="col-md-6">
                    <div class="form-group" :class="{'has-danger': errors.telefono}">
                      <label class="control-label">Telefono</label>
                      <el-input v-model="form.telefono"></el-input>
                      <small class="form-control-feedback" v-if="errors.telefono" v-text="errors.telefono[0]"></small>
                    </div>
                  </div>
                  <div class="col-md-6">
                    <div class="form-group" :class="{'has-danger': errors.email}">
                      <label class="control-label">Email</label>
                      <el-input v-model="form.email"></el-input>
                      <small class="form-control-feedback" v-if="errors.email" v-text="errors.email[0]"></small>
                    </div>
                  </div>
                </div>

                <div class="row m-t-10">
                  <div class="col-md-12 text-center">
                    <el-button icon="el-icon-plus"
                               class="btn-add-address"
                               size="mini"
                               @click.prevent="clickAddEmails()">
                      Agregar Email/Telefono
                    </el-button>
                  </div>
                </div>

                <div v-for="(row, index) in form.emails" class="row m-t-10">
                  <div class="col-md-12">
                    <label class="control-label">
                      # {{ index + 1 }}
                      <el-button class="btn-default-danger"
                                 icon="el-icon-minus"
                                 size="mini"
                                 @click.prevent="clickRemoveEmails(index)">Eliminar Emails/Telefonos
                      </el-button>
                    </label>
                  </div>
                  <div class="col-md-6">
                    <div class="form-group" :class="{'has-danger': errors.telefono}">
                      <label class="control-label">Telefono</label>
                      <el-input v-model="row.telefono"></el-input>
                      <small class="form-control-feedback" v-if="errors.telefono" v-text="errors.telefono[0]"></small>
                    </div>
                  </div>
                  <div class="col-md-6">
                    <div class="form-group" :class="{'has-danger': errors.email}">
                      <label class="control-label">Email</label>
                      <el-input v-model="row.email"></el-input>
                      <small class="form-control-feedback" v-if="errors.email" v-text="errors.email[0]"></small>
                    </div>
                  </div>
                </div>



            </div>
            <div class="form-actions text-right pt-2">
                <el-button class="second-buton" @click.prevent="handleCloseDialog()">Cancelar</el-button>
                <el-button type="primary" native-type="submit" :loading="loading_submit">Guardar</el-button>
            </div>
        </form>
    </el-dialog>
</template>

<script>


    export default {
        props: ['showDialog', 'recordId', 'context', 'empresaId', 'empresaEntity'],
        data() {
            return {
                loading_submit: false,
                titleDialog: null,
                resource: 'comercial/contactos',
                errors: {},
                form: {},
                headers: headers_token,
                list_empresas: [],
                list_estados_interno: [],
                loading: false,
                searchTimeout: null,
                lastSearch: '',
                isInitialized: false
            }
        },
        async created() {
          await this.$http.get(`/${this.resource}/tables`)
            .then(response => {
              this.list_empresas = response.data.list_empresas
              this.list_estados_interno = response.data.list_estados_interno
            })

          if (this.showDialog) {
            if (this.recordId) {
              // Modo edición
              this.titleDialog = 'Editar Contacto';
              this.$nextTick(() => {
                this.loadContactData();
              });
            } else {
              // Modo creación
              this.titleDialog = 'Nuevo Contacto';
              this.initForm();

              // Pre-cargar empresa si existe
              if (this.empresaEntity && this.empresaEntity.id) {
                this.$nextTick(() => {
                  this.$nextTick(() => {
                    this.preloadEmpresa();
                  });
                });
              }
            }

            this.isInitialized = true;
          }
        },
        watch: {
          recordId: {
            immediate: true,
            handler(newVal, oldVal) {
              // Solo cargar si el diálogo está visible y hay un recordId válido
              if (this.showDialog && newVal && newVal !== oldVal) {
                this.$nextTick(() => {
                  this.loadContactData();
                });
              }
            }
          },
          showDialog: {
            immediate: false,
            handler(newVal, oldVal) {
              if (newVal && !oldVal) {
                if (this.recordId) {
                  this.titleDialog = 'Editar Contacto';
                  this.$nextTick(() => {
                    this.loadContactData();
                  });
                } else {
                  // Modo creación
                  this.titleDialog = 'Nuevo Contacto';
                  this.initForm();

                  // Pre-cargar empresa si existe
                  if (this.empresaEntity && this.empresaEntity.id) {
                    // Usar múltiples nextTick para asegurar que el DOM esté listo
                    this.$nextTick(() => {
                      this.$nextTick(() => {
                        this.preloadEmpresa();
                      });
                    });
                  }
                }

                this.isInitialized = true;
              } else if (!newVal && oldVal) {
                // El diálogo se acaba de cerrar
                this.isInitialized = false;
              }
            }
          },
          // Agregar watcher para empresaEntity
          empresaEntity: {
            deep: true,
            handler(newVal, oldVal) {
              // Si el diálogo está abierto, no hay recordId (nuevo contacto) y hay una empresa
              if (this.showDialog && !this.recordId && newVal && newVal.id) {
                this.$nextTick(() => {
                  this.preloadEmpresa();
                });
              }
            }
          }
        },
        methods: {
            onOpen() {
              // Si ya está inicializado por los watchers, no hacer nada
              if (this.isInitialized) {
                return;
              }

              this.errors = {};

              if (this.recordId) {
                this.titleDialog = 'Editar Contacto';
                this.$nextTick(() => {
                  this.loadContactData();
                });
              } else {
                this.titleDialog = 'Nuevo Contacto';
                this.initForm();

                if (this.empresaEntity && this.empresaEntity.id) {
                  this.$nextTick(() => {
                    this.preloadEmpresa();
                  });
                }
              }

              this.isInitialized = true;
            },
            preloadEmpresa() {
              if (!this.empresaEntity || !this.empresaEntity.id) {
                return;
              }

              // Extraer datos de la empresa (manejar Getters & Setters de Vue)
              const empresaId = parseInt(this.empresaEntity.id);
              const empresaRazon = this.empresaEntity.razon_social || this.empresaEntity.nombre_comercial || 'Empresa';

              const empresaToAdd = {
                id: empresaId,
                razon_social: empresaRazon
              };

              // Buscar si ya existe en la lista
              const existsIndex = this.list_empresas.findIndex(e => e.id === empresaId);

              if (existsIndex === -1) {
                this.list_empresas.unshift(empresaToAdd);
              } else {
                this.$set(this.list_empresas, existsIndex, empresaToAdd);
              }

              // Asignar el ID al formulario
              this.form.empresa_id = empresaId;

              // Forzar actualización del componente
              this.$forceUpdate();

              this.$nextTick(() => {
                this.originalForm = JSON.stringify(this.form);
              });
            },

            loadContactData() {
              this.loading = true;
              this.$http.get(`/${this.resource}/record/${this.recordId}`)
                .then(response => {
                  const data = response.data.data;

                  // Validar que data existe
                  if (!data) {
                    this.$message.error('No se pudieron cargar los datos del contacto');
                    this.forceCloseDialog();
                    return;
                  }

                  // Asignar todos los campos del formulario
                  this.form = {
                    id: data.id,
                    empresa_id: data.empresa_id,
                    nombres: data.nombres,
                    apellidos: data.apellidos,
                    cargo: data.cargo,
                    celular: data.celular,
                    estado: Number(data.estado),
                    origen: data.origen,
                    tipo_contacto: data.tipo_contacto,
                    fecha_cumpleanos: data.fecha_cumpleanos,
                    direccion: data.direccion,
                    emails: Array.isArray(data.emails) ? data.emails : [],
                    telefono: data.telefono,
                    email: data.email,
                  };

                  // Manejar la empresa en el select
                  if (data.empresa_id) {
                    let empresaNombre = 'Empresa';

                    // Intentar obtener el nombre de la empresa de diferentes formas
                    if (data.empresa) {
                      // Si viene como objeto
                      empresaNombre = data.empresa.razon_social || data.empresa.nombre_comercial || 'Empresa';
                    } else if (data.razon_social_empresa) {
                      // Si viene como campo directo
                      empresaNombre = data.razon_social_empresa;
                    }

                    // Verificar si la empresa ya está en la lista
                    const empresaExiste = this.list_empresas.find(e => e.id === data.empresa_id);

                    if (!empresaExiste) {
                      this.list_empresas.unshift({
                        id: data.empresa_id,
                        razon_social: empresaNombre
                      });
                    }
                  }

                  // Guardar estado original del formulario
                  this.$nextTick(() => {
                    this.originalForm = JSON.stringify(this.form);
                  });
                })
                .catch(error => {
                  this.$message.error('No se pudo cargar el registro para editar');
                  this.forceCloseDialog();
                })
                .finally(() => {
                  this.loading = false;
                });
            },
            handleCloseDialog() {
              if (this.hasUnsavedChanges()) {
                this.$confirm('¿Estás seguro de cerrar el formulario? Se perderán los datos no guardados.', 'Confirmar', {
                  confirmButtonText: 'Cerrar sin guardar',
                  cancelButtonText: 'Cancelar',
                  type: 'warning'
                }).then(() => {
                  this.forceCloseDialog()
                }).catch(() => {

                });
              } else {
                this.forceCloseDialog()
              }
            },
            forceCloseDialog() {
              this.initForm()
              this.isInitialized = false
              this.$emit('update:showDialog', false)
              this.$emit('update:recordId', null)
            },
            hasUnsavedChanges() {
                return JSON.stringify(this.form) !== this.originalForm
            },
            async getEmpresas(query) {
              if (query === this.lastSearch) return;

              if (!query || query.length < 3) {
                // No limpiar la lista si hay una empresa pre-cargada
                if (!this.form.empresa_id) {
                  this.list_empresas = [];
                }
                this.lastSearch = query;
                return;
              }

              // Debounce
              if (this.searchTimeout) {
                clearTimeout(this.searchTimeout);
              }

              this.searchTimeout = setTimeout(async () => {
                this.loading = true;
                this.lastSearch = query;

                try {
                  const response = await this.$http.get(`/comercial/empresas/search`, {
                    params: {
                      search: query,
                      limit: 50
                    }
                  });

                  this.list_empresas = response.data.data || response.data;

                  // Si hay una empresa pre-seleccionada que no está en los resultados, agrégala
                  if (this.form.empresa_id && this.empresaEntity) {
                    const exists = this.list_empresas.find(e => e.id === this.form.empresa_id);
                    if (!exists) {
                      this.list_empresas.unshift({
                        id: this.form.empresa_id,
                        razon_social: this.empresaEntity.razon_social
                      });
                    }
                  }
                } catch (error) {
                  this.list_empresas = [];
                } finally {
                  this.loading = false;
                }
              }, 400);
            },
            handleFocus() {
              if (!this.form.empresa_id && this.list_empresas.length === 0) {
                this.getEmpresas('');
              }
            },
            initForm() {
                this.errors = {}
                this.form = {
                    id: null,
                    empresa_id: null,
                    nombres: null,
                    apellidos: null,
                    cargo: null,
                    celular: null,
                    email: null,
                    telefono:null,
                    emails: [],
                    estado: 1,
                    origen: null,
                    tipo_contacto: null,
                    fecha_cumpleanos: null,
                    direccion: null
                }
                this.originalForm = JSON.stringify(this.form)
            },
            async submit() {
                this.loading_submit = true
                this.$http.post(`/${this.resource}`, this.form)
                    .then(response => {
                        if (response.data.success) {
                            this.$message.success(response.data.message)
                            if (this.context === 'empresas') {
                              this.$emit('contactSaved', this.empresaId || this.form.empresa_id);
                            } else {
                              this.$eventHub.$emit('reloadData');
                            }
                            this.close()
                        } else {
                            this.$message.error(response.data.message)
                        }
                    })
                    .catch(error => {
                        if (error.response.status === 422) {
                            this.errors = error.response.data
                        }
                    })
                    .then(() => {
                        this.loading_submit = false
                    })

            },

            close() {
              this.$emit('update:showDialog', false)
              this.$emit('update:recordId', null)
              this.initForm()
              this.isInitialized = false
            },

            clickAddEmails() {
              this.form.emails.push({
                'id': null,
                'telefono': null,
                'email': null,
              });
            },
            clickRemoveEmails(index) {
              this.form.emails.splice(index, 1);
            },
        }
    }
</script>
<style>
.avatar-uploader {
    width: 178px;
    height: 178px;
}
.avatar {
    width: 100%;
    height: 100%;
    object-fit: cover;
}
.avatar-uploader-icon {
    font-size: 28px;
    color: #8c8c8c;
    line-height: 178px;
    text-align: center;
    max-width: 178px;
}
</style>
