___CSS_LOADER_EXPORT___.push([module.id, "\n.font-custom {\n    font-size: 15px !important\n}\n", "",{"version":3,"sources":["webpack://./modules/Expense/Resources/assets/js/components/DataTableExpenses.vue"],"names":[],"mappings":";AAoIA;IACA;AACA","sourcesContent":["<template>\n    <div>\n        <div class=\"row\">\n\n            <div class=\"col-md-12 col-lg-12 col-xl-12 \">\n\n                <div class=\"row mt-2\">\n\n                    <div class=\"col-md-3\">\n                        <label class=\"control-label\">Periodo</label>\n                        <el-select v-model=\"form.period\"\n                                   @change=\"changePeriod\">\n                            <el-option key=\"month\"\n                                       label=\"Por mes\"\n                                       value=\"month\"></el-option>\n                            <el-option key=\"between_months\"\n                                       label=\"Entre meses\"\n                                       value=\"between_months\"></el-option>\n                            <el-option key=\"date\"\n                                       label=\"Por fecha\"\n                                       value=\"date\"></el-option>\n                            <el-option key=\"between_dates\"\n                                       label=\"Entre fechas\"\n                                       value=\"between_dates\"></el-option>\n                        </el-select>\n                    </div>\n                    <template v-if=\"form.period === 'month' || form.period === 'between_months'\">\n                        <div class=\"col-md-3\">\n                            <label class=\"control-label\">Mes de</label>\n                            <el-date-picker v-model=\"form.month_start\"\n                                            :clearable=\"false\"\n                                            format=\"MM/yyyy\"\n                                            type=\"month\"\n                                            value-format=\"yyyy-MM\"\n                                            @change=\"changeDisabledMonths\"></el-date-picker>\n                        </div>\n                    </template>\n                    <template v-if=\"form.period === 'between_months'\">\n                        <div class=\"col-md-3\">\n                            <label class=\"control-label\">Mes al</label>\n                            <el-date-picker v-model=\"form.month_end\"\n                                            :clearable=\"false\"\n                                            :picker-options=\"pickerOptionsMonths\"\n                                            format=\"MM/yyyy\"\n                                            type=\"month\"\n                                            value-format=\"yyyy-MM\"></el-date-picker>\n                        </div>\n                    </template>\n                    <template v-if=\"form.period === 'date' || form.period === 'between_dates'\">\n                        <div class=\"col-md-3\">\n                            <label class=\"control-label\">Fecha del</label>\n                            <el-date-picker v-model=\"form.date_start\"\n                                            :clearable=\"false\"\n                                            format=\"dd/MM/yyyy\"\n                                            type=\"date\"\n                                            value-format=\"yyyy-MM-dd\"\n                                            @change=\"changeDisabledDates\"></el-date-picker>\n                        </div>\n                    </template>\n                    <template v-if=\"form.period === 'between_dates'\">\n                        <div class=\"col-md-3\">\n                            <label class=\"control-label\">Fecha al</label>\n                            <el-date-picker v-model=\"form.date_end\"\n                                            :clearable=\"false\"\n                                            :picker-options=\"pickerOptionsDates\"\n                                            format=\"dd/MM/yyyy\"\n                                            type=\"date\"\n                                            value-format=\"yyyy-MM-dd\"></el-date-picker>\n                        </div>\n                    </template>\n\n                    <div class=\"col-lg-7 col-md-7 col-md-7 col-sm-12\"\n                         style=\"margin-top:29px\">\n                        <el-button :loading=\"loading_submit\"\n                                   class=\"submit\"\n                                   icon=\"el-icon-search\"\n                                   type=\"primary\"\n                                   @click.prevent=\"getRecordsByFilter\">Buscar\n                        </el-button>\n\n                        <template v-if=\"records.length>0\">\n\n                            <el-button class=\"submit\"\n                                       type=\"success\"\n                                       @click.prevent=\"clickDownload('excel')\"><i class=\"fa fa-file-excel\"></i> Exportal\n                                                                                                                Excel\n                            </el-button>\n\n                        </template>\n\n                    </div>\n\n                </div>\n                <div class=\"row mt-1 mb-4\">\n\n                </div>\n            </div>\n\n\n            <div class=\"col-md-12\">\n                <div class=\"scroll-shadow shadow-left\" v-show=\"showLeftShadow\"></div>\n                <div class=\"scroll-shadow shadow-right\" v-show=\"showRightShadow\"></div>\n\n                <div class=\"table-responsive\" ref=\"scrollContainer\">\n                    <table class=\"table\">\n                       <thead>\n                            <slot name=\"heading\"></slot>\n                        </thead>\n                        <tbody>\n                            <slot\n                                v-for=\"(row, index) in records\"\n                                :row=\"row\"\n                                :index=\"customIndex(index)\"\n                            ></slot>\n                        </tbody>\n                    </table>\n                    <div>\n                        <el-pagination\n                            :current-page.sync=\"pagination.current_page\"\n                            :page-size=\"pagination.per_page\"\n                            :total=\"pagination.total\"\n                            layout=\"total, prev, pager, next\"\n                            @current-change=\"getRecords\">\n                        </el-pagination>\n                    </div>\n                </div>\n            </div>\n        </div>\n\n    </div>\n</template>\n<style>\n.font-custom {\n    font-size: 15px !important\n}\n</style>\n<script>\n\nimport moment from 'moment'\nimport queryString from 'query-string'\n\nexport default {\n    props: {\n        resource: String,\n        applyCustomer: {\n            type: Boolean,\n            required: false,\n            default: false\n        },\n        visibleColumns: Object\n    },\n    data() {\n        return {\n            loading_submit: false,\n            persons: [],\n            all_persons: [],\n            loading_search: false,\n            columns: [],\n            records: [],\n            headers: headers_token,\n            document_types: [],\n            pagination: {},\n            search: {},\n            totals: {},\n            establishment: null,\n            establishments: [],\n            web_platforms: [],\n            state_types: [],\n            users: [],\n            form: {\n                document_type_id: null,\n                user_type: null,\n                user_id: [],\n            },\n            pickerOptionsDates: {\n                disabledDate: (time) => {\n                    time = moment(time).format('YYYY-MM-DD')\n                    return this.form.date_start > time\n                }\n            },\n            pickerOptionsMonths: {\n                disabledDate: (time) => {\n                    time = moment(time).format('YYYY-MM')\n                    return this.form.month_start > time\n                }\n            },\n            sellers: [],\n            items: [],\n            all_items: [],\n            loading_search_items: false,\n            showLeftShadow: false,\n            showRightShadow: false,\n        }\n    },\n    computed: {\n        cantChoiseUserWithUserType(){\n            if(this.form.user_type && this.form.user_type.length > 1) return false;\n            return true;\n        }\n    },\n    created() {\n        this.initForm()\n        this.$eventHub.$on('reloadData', () => {\n            this.getRecords()\n        })\n    },\n    async mounted() {\n        await this.getRecords()\n\n        this.$nextTick(() => {\n            const el = this.$refs.scrollContainer;\n            if (el) {\n                el.addEventListener('scroll', this.checkScrollShadows);\n                this.checkScrollShadows();\n            }\n        });\n    },\n    methods: {\n        checkScrollShadows() {\n            const el = this.$refs.scrollContainer;\n            if (!el) return;\n\n            const scrollLeft = el.scrollLeft;\n            const scrollRight = el.scrollWidth - el.clientWidth - scrollLeft;\n\n            this.showLeftShadow = scrollLeft > 1;\n            this.showRightShadow = scrollRight > 1;\n        },\n        clickDownload(type) {\n            let query = queryString.stringify({\n                ...this.form\n            });\n            delete(query.user_id)\n            delete(query.document_type_id)\n\n            window.open(`/${this.resource}/report/${type}/?${this.getQueryParameters()}`, '_blank');\n        },\n\n        initForm() {\n\n            this.form = {\n                establishment_id: null,\n                person_id: null,\n                type_person: null,\n                document_type_id: null,\n                period: 'month',\n                date_start: moment().format('YYYY-MM-DD'),\n                date_end: moment().format('YYYY-MM-DD'),\n                month_start: moment().format('YYYY-MM'),\n                month_end: moment().format('YYYY-MM'),\n                seller_id: null,\n                state_type_id: null,\n                include_categories: false,\n                guides: null,\n                user_type: null,\n                user_id: [],\n                item_id: null\n            }\n\n        },\n        \n        customIndex(index) {\n            return (this.pagination.per_page * (this.pagination.current_page - 1)) + index + 1\n        },\n        async getRecordsByFilter() {\n\n            this.loading_submit = await true\n            await this.getRecords()\n            this.loading_submit = await false\n\n        },\n        getRecords() {\n            return this.$http.get(`/${this.resource}/records?${this.getQueryParameters()}`).then((response) => {\n                this.records = response.data.data\n                this.pagination = response.data.meta\n                this.pagination.per_page = parseInt(response.data.meta.per_page)\n                this.loading_submit = false\n            });\n\n        },\n        getQueryParameters() {\n            if(this.users.length  > 0){\n                // delete(this.form.type_person)\n            }\n            let parameters = queryString.stringify({\n                page: this.pagination.current_page,\n                limit: this.limit,\n                ...this.form\n            })\n            delete(parameters.user_id)\n            delete(parameters.document_type_id)\n\n            return `${parameters}&user_id=${JSON.stringify(this.form.user_id)}&document_type_id=${JSON.stringify(this.form.document_type_id)}`\n\n        },\n\n        changeDisabledDates() {\n            if (this.form.date_end < this.form.date_start) {\n                this.form.date_end = this.form.date_start\n            }\n            // this.loadAll();\n        },\n        changeDisabledMonths() {\n            if (this.form.month_end < this.form.month_start) {\n                this.form.month_end = this.form.month_start\n            }\n        },\n        changePeriod() {\n            if (this.form.period === 'month') {\n                this.form.month_start = moment().format('YYYY-MM');\n                this.form.month_end = moment().format('YYYY-MM');\n            }\n            if (this.form.period === 'between_months') {\n                this.form.month_start = moment().startOf('year').format('YYYY-MM'); //'2019-01';\n                this.form.month_end = moment().endOf('year').format('YYYY-MM');\n\n            }\n            if (this.form.period === 'date') {\n                this.form.date_start = moment().format('YYYY-MM-DD');\n                this.form.date_end = moment().format('YYYY-MM-DD');\n            }\n            if (this.form.period === 'between_dates') {\n                this.form.date_start = moment().startOf('month').format('YYYY-MM-DD');\n                this.form.date_end = moment().endOf('month').format('YYYY-MM-DD');\n            }\n        },\n        getSearch() {\n            return this.search;\n        }\n    }\n}\n</script>\n"],"sourceRoot":""}]);
