___CSS_LOADER_EXPORT___.push([module.id, "\n.el-select-dropdown {\n    margin-right: 5% !important;\n    max-width: 80% !important;\n}\n", "",{"version":3,"sources":["webpack://./modules/Purchase/Resources/assets/js/views/purchase-quotations/partials/item.vue"],"names":[],"mappings":";AAiHA;IACA,2BAAA;IACA,yBAAA;AACA","sourcesContent":["<template>\n    <el-dialog :close-on-click-modal=\"false\"\n               :title=\"titleDialog\"\n               :visible=\"showDialog\"\n               top=\"7vh\"\n               @close=\"close\"\n               @open=\"create\">\n        <form autocomplete=\"off\"\n              @submit.prevent=\"clickAddItem\">\n            <div class=\"form-body\">\n                <div class=\"row\">\n                    <div class=\"col-md-8\">\n                        <div id=\"custom-select\"\n                             :class=\"{'has-danger': errors.item_id}\"\n                             class=\"form-group\">\n                            <label class=\"control-label\">\n                                Producto/Servicio\n                                <a v-if=\"can_add_new_product\"\n                                   href=\"#\"\n                                   @click.prevent=\"showDialogNewItem = true\">\n                                    [+ Nuevo]\n                                </a>\n                            </label>\n                            <template id=\"select-append\">\n                                <el-input id=\"custom-input\" class=\"input-search-product\">\n\n                                    <el-select\n                                        id=\"select-width\"\n                                        ref=\"selectSearchNormal\"\n                                        slot=\"prepend\"\n                                        v-model=\"form.item_id\"\n                                        :disabled=\"recordItem != null\"\n                                        :loading=\"loading_search\"\n                                        :remote-method=\"searchRemoteItems\"\n                                        filterable\n                                        placeholder=\"Buscar\"\n                                        popper-class=\"el-select-items\"\n                                        remote\n                                        @change=\"changeItem\"\n                                        @focus=\"focusSelectItem\">\n\n\n                                        <el-tooltip\n                                            v-for=\"option in items\"\n                                            :key=\"option.id\"\n                                            placement=\"left\">\n                                            <div\n                                                slot=\"content\"\n                                                v-html=\"ItemSlotTooltipView(option)\"\n                                            ></div>\n                                            <el-option\n                                                :label=\"ItemOptionDescriptionView(option)\"\n                                                :value=\"option.id\"\n                                            ></el-option>\n\n                                        </el-tooltip>\n                                    </el-select>\n                                    <!--\n                                    <el-tooltip\n                                        slot=\"append\"\n                                        :disabled=\"recordItem != null\"\n                                        class=\"item\"\n                                        content=\"Ver Stock del Producto\"\n                                        effect=\"dark\"\n                                        placement=\"bottom\">\n                                        <el-button\n                                            @click.prevent=\"clickWarehouseDetail()\">\n                                            <i class=\"fa fa-search\"></i>\n                                        </el-button>\n                                    </el-tooltip>\n                                    -->\n                                </el-input>\n                            </template>\n\n                            <small v-if=\"errors.item_id\"\n                                   class=\"form-control-feedback\"\n                                   v-text=\"errors.item_id[0]\"></small>\n                        </div>\n                    </div>\n                    <div class=\"col-md-4\">\n                        <div :class=\"{'has-danger': errors.quantity}\"\n                             class=\"form-group\">\n                            <label class=\"control-label\">Cantidad</label>\n                            <el-input-number v-model=\"form.quantity\"\n                                             :disabled=\"form.item.calculate_quantity\"\n                                             :min=\"0.01\"></el-input-number>\n                            <small v-if=\"errors.quantity\"\n                                   class=\"form-control-feedback\"\n                                   v-text=\"errors.quantity[0]\"></small>\n                        </div>\n                    </div>\n                </div>\n            </div>\n            <div class=\"form-actions text-right mt-4\">\n                <el-button class=\"second-buton\" @click.prevent=\"close()\">Cerrar</el-button>\n                <el-button v-if=\"form.item_id\"\n                           class=\"add\"\n                           native-type=\"submit\"\n                           type=\"primary\">Agregar\n                </el-button>\n            </div>\n        </form>\n        <item-form :external=\"true\"\n                   :showDialog.sync=\"showDialogNewItem\"></item-form>\n\n        <warehouses-detail\n            :showDialog.sync=\"showWarehousesDetail\"\n            :warehouses=\"warehousesDetail\">\n        </warehouses-detail>\n\n    </el-dialog>\n</template>\n<style>\n.el-select-dropdown {\n    margin-right: 5% !important;\n    max-width: 80% !important;\n}\n</style>\n<script>\n\nimport itemForm from '../../../../../../../../resources/js/views/tenant/items/form.vue'\nimport WarehousesDetail from '@views/documents/partials/select_warehouses.vue'\nimport {mapActions, mapState} from \"vuex/dist/vuex.mjs\";\nimport {ItemOptionDescription, ItemSlotTooltip} from \"../../../../../../../../resources/js/helpers/modal_item\";\n\nexport default {\n    props: [\n        'recordItem',\n        'showDialog',\n    ],\n    components: {\n        itemForm,\n        WarehousesDetail,\n    },\n    data() {\n        return {\n            can_add_new_product: true,\n            loading_search: false,\n            titleDialog: 'Agregar Producto o Servicio',\n            resource: 'purchase-quotations',\n            showDialogNewItem: false,\n            errors: {},\n            form: {},\n            all_items: [],\n            items: [],\n            aux_items: [],\n            showWarehousesDetail: false,\n            warehousesDetail: [],\n        }\n    },\n    async created() {\n        this.loadConfiguration()\n        await this.initForm()\n        await this.getItems();\n\n        this.$eventHub.$on('reloadDataItems', (item_id) => {\n            this.reloadDataItems(item_id)\n        })\n    },\n\n    computed: {\n\n        ...mapState([\n            'config',\n        ]),\n    },\n    methods: {\n        ...mapActions([\n            'loadConfiguration',\n        ]),\n\n        clickWarehouseDetail() {\n\n            if (!this.form.item_id) {\n                return this.$message.error('Seleccione un item');\n            }\n\n            let item = _.find(this.items, {'id': this.form.item_id});\n\n            this.warehousesDetail = item.warehouses\n            this.showWarehousesDetail = true\n        },\n        async searchRemoteItems(input) {\n            if (input.length > 2) {\n                this.loading_search = true\n                const params = {\n                    'input': input,\n                    'search_by_barcode': this.search_item_by_barcode ? 1 : 0\n                }\n                await this.$http.get(`/${this.resource}/search-items/`, {params})\n                    .then(response => {\n                        this.items = response.data.items\n                        this.loading_search = false\n                        this.enabledSearchItemsBarcode()\n                        this.enabledSearchItemBySeries()\n                        if (this.items.length == 0) {\n                            this.filterItems()\n                        }\n                    })\n            } else {\n                await this.filterItems()\n            }\n        },\n\n        filterItems() {\n            this.items = this.all_items\n        },\n        enabledSearchItemsBarcode() {\n            if (this.search_item_by_barcode) {\n                this.$refs.selectBarcode.$data.selectedLabel = '';\n                if (this.items.length == 1) {\n                    this.form.item_id = this.items[0].id;\n                    this.$refs.selectBarcode.blur();\n                    this.changeItem();\n                }\n            }\n        },\n        async enabledSearchItemBySeries() {\n\n            if (this.config.search_item_by_series && this.items.length == 1) {\n\n                this.$notify({title: \"Serie ubicada\", message: \"Producto añadido!\", type: \"success\", duration: 1200});\n                this.form.item_id = this.items[0].id;\n                this.$refs.selectSearchNormal.$data.selectedLabel = '';\n\n                await this.changeItem();\n\n                this.lots = await this.form.item.lots.map((lot) => {\n                    lot.has_sale = true\n                })\n\n                await this.clickAddItem()\n\n                this.$refs.selectSearchNormal.$data.selectedLabel = '';\n            }\n\n            if (this.config.search_item_by_series && this.items.length == 0) {\n                this.$notify({title: \"Serie no ubicada\", message: \"\", type: \"warning\", duration: 1200});\n            }\n\n        },\n\n        initForm() {\n            this.errors = {};\n\n            this.form = {\n                item_id: null,\n                item: {},\n                quantity: 1,\n                unit_type_id: null,\n                is_set: false,\n            };\n\n        },\n\n        ItemSlotTooltipView(item) {\n            return ItemSlotTooltip(item);\n        },\n        ItemOptionDescriptionView(item) {\n            return ItemOptionDescription(item)\n        },\n        create() {\n        },\n        close() {\n            this.initForm()\n            this.$emit('update:showDialog', false)\n        },\n        changeItem() {\n            this.form.item = _.find(this.items, {'id': this.form.item_id});\n            this.form.quantity = 1;\n        },\n        clickAddItem() {\n\n            // this.form.affectation_igv_type = _.find(this.affectation_igv_types, {'id': this.form.affectation_igv_type_id});\n            // this.row = calculateRowItem(this.form, this.currencyTypeIdActive, this.exchangeRateSale);\n            this.$emit('add', this.form);\n            this.initForm();\n            this.setFocusSelectItem()\n        },\n        setFocusSelectItem() {\n            this.$refs.selectSearchNormal.$el.getElementsByTagName('input')[0].focus()\n        },\n        getItems() {\n            this.$http.get(`/${this.resource}/item/tables`).then(response => {\n                this.items = response.data.items\n            })\n        },\n        reloadDataItems(item_id) {\n            this.$http.get(`/${this.resource}/table/items`).then((response) => {\n                this.items = response.data\n                this.form.item_id = item_id\n                this.changeItem()\n                // this.filterItems()\n\n            })\n        },\n        focusSelectItem() {\n            this.$refs.selectSearchNormal.$el.getElementsByTagName('input')[0].focus()\n        },\n    }\n}\n\n</script>\n"],"sourceRoot":""}]);
