___CSS_LOADER_EXPORT___.push([module.id, "\n@media only screen and (max-width: 485px){\n.filter-container{\n      margin-top: 0px;\n& .btn-filter-content, .btn-container-mobile{\n        display: flex;\n        align-items: center;\n        justify-content: start;\n}\n}\n}\n", "",{"version":3,"sources":["webpack://./modules/Item/Resources/assets/js/views/item-lots/index.vue"],"names":[],"mappings":";AAyHA;AACA;MACA,eAAA;AACA;QACA,aAAA;QACA,mBAAA;QACA,sBAAA;AACA;AACA;AACA","sourcesContent":["<template>\n    <div>\n        <div class=\"page-header pr-0\">\n            <h2><a href=\"/item-lots\">\n                <svg  xmlns=\"http://www.w3.org/2000/svg\" style=\"margin-top: -5px;\"  width=\"24\"  height=\"24\"  viewBox=\"0 0 24 24\"  fill=\"none\"  stroke=\"currentColor\"  stroke-width=\"2\"  stroke-linecap=\"round\"  stroke-linejoin=\"round\"  class=\"icon icon-tabler icons-tabler-outline icon-tabler-category-2\"><path stroke=\"none\" d=\"M0 0h24v24H0z\" fill=\"none\"/><path d=\"M14 4h6v6h-6z\" /><path d=\"M4 14h6v6h-6z\" /><path d=\"M17 17m-3 0a3 3 0 1 0 6 0a3 3 0 1 0 -6 0\" /><path d=\"M7 7m-3 0a3 3 0 1 0 6 0a3 3 0 1 0 -6 0\" /></svg>\n            </a></h2>\n            <ol class=\"breadcrumbs\">\n                <li class=\"active\"><span>{{ title }}</span></li>\n            </ol>\n            <div class=\"right-wrapper pull-right\">\n                <button type=\"button\" class=\"btn btn-success btn-sm  mt-2 mr-2\" @click.prevent=\"clickExport()\"><i class=\"fa fa-file-excel\"></i> Exportar</button>\n            </div>\n        </div>\n        <div class=\"card tab-content-default row-new mb-0\">\n            <!-- <div class=\"card-header bg-info\">\n                <h3 class=\"my-0\">Listado de {{ title }}</h3>\n            </div> -->\n            <div class=\"card-body\">\n             \n                <div v-loading=\"loading_submit\">\n                    <div class=\"row \">   \n                        <div class=\"col-md-12 col-lg-12 col-xl-12 filter-container\">\n                            <div class=\"btn-filter-content\">\n                                <el-button\n                                    type=\"secondary\"\n                                    class=\"btn-show-filter mb-2\"\n                                    :class=\"{ shift: isVisible }\"\n                                    @click=\"toggleInformation\"\n                                >\n                                    {{ isVisible ? \"Ocultar filtros\" : \"Mostrar filtros\" }}\n                                </el-button>\n                            </div>\n                            <div class=\"row\" v-if=\"isVisible\">\n                                <div class=\"col-lg-4 col-md-4 col-sm-12 pb-2\">\n                                    <div class=\"d-flex\">\n                                        <div class=\"d-flex align-items-center\" style=\"width:100px\">\n                                            Filtrar por:\n                                        </div>\n                                        <el-select v-model=\"search.column\"  placeholder=\"Select\" @change=\"changeClearInput\">\n                                            <el-option v-for=\"(label, key) in columns\" :key=\"key\" :value=\"key\" :label=\"label\"></el-option>\n                                        </el-select>\n                                    </div>\n                                </div>\n                                <div class=\"col-lg-3 col-md-4 col-sm-12 pb-2\">\n                                    <template v-if=\"search.column=='date'\">\n                                        <el-date-picker\n                                            v-model=\"search.value\"\n                                            type=\"date\"\n                                            style=\"width: 100%;\"\n                                            placeholder=\"Buscar\"\n                                            value-format=\"yyyy-MM-dd\"\n                                            @change=\"getRecords\">\n                                        </el-date-picker>\n                                    </template>\n                                    <template v-else>\n                                        <el-input placeholder=\"Buscar\"\n                                            v-model=\"search.value\"\n                                            style=\"width: 100%;\"\n                                            prefix-icon=\"el-icon-search\"\n                                            @input=\"getRecords\">\n                                        </el-input>\n                                    </template>\n                                </div>\n                            </div>\n                        </div>\n\n                        <div class=\"col-md-12\">\n                            <div class=\"scroll-shadow shadow-left\" v-show=\"showLeftShadow\"></div>\n                            <div class=\"scroll-shadow shadow-right\" v-show=\"showRightShadow\"></div>\n\n                            <div class=\"table-responsive\" ref=\"scrollContainer\">\n                                <table class=\"table\">\n                                    <thead>\n                                        <tr>\n                                            <!-- <th>#</th> -->\n                                            <th>Serie</th>\n                                            <th>Producto</th>\n                                            <th>Fecha</th>\n                                            <th>Estado</th>\n                                            <th>Vendido</th>\n                                            <th class=\"text-right\">Acciones</th>\n                                        </tr>\n                                    </thead>\n                                    <tbody>\n                                        <tr v-for=\"(row, index) in records\" :key=\"index\">\n                                            <!-- <td>{{ customIndex(index) }}</td> -->\n                                            <td>{{ row.series }}</td>\n                                            <td>{{ row.item_description }}</td>\n                                            <td>{{ row.date }}</td>\n                                            <td>{{ row.state }}</td>\n                                            <td>{{ row.status }}</td>\n                                            <td class=\"text-right\">\n                                                <button type=\"button\" class=\"btn waves-effect waves-light btn-xs btn-info\" @click.prevent=\"clickCreate(row.id)\" v-if=\"!row.has_sale\">Editar</button>\n                                            </td>\n                                        </tr>\n                                    </tbody>\n                                </table>\n                                <div>\n                                    <el-pagination\n                                            @current-change=\"getRecords\"\n                                            layout=\"total, prev, pager, next\"\n                                            :total=\"pagination.total\"\n                                            :current-page.sync=\"pagination.current_page\"\n                                            :page-size=\"pagination.per_page\">\n                                    </el-pagination>\n                                </div>\n                            </div>\n                        </div>\n \n                    </div>\n                </div>\n            </div>\n\n            <item-lot-form \n                :showDialog.sync=\"showDialog\"\n                :recordId=\"recordId\"\n                    ></item-lot-form> \n        </div>\n    </div>\n</template>\n<style>\n@media only screen and (max-width: 485px){\n    .filter-container{\n      margin-top: 0px;\n      & .btn-filter-content, .btn-container-mobile{\n        display: flex;\n        align-items: center;\n        justify-content: start;\n      }\n    }\n}\n</style>\n<script>\n\n    import ItemLotForm from './form.vue' \n    import queryString from 'query-string'\n\n    export default {\n        components: {ItemLotForm},\n        data() {\n            return {\n                title: null,\n                showDialog: false, \n                resource: 'item-lots',\n                recordId: null,\n                search: {\n                    column: null,\n                    value: null\n                },\n                columns: [],\n                records: [],\n                pagination: {},\n                isVisible: false,\n                loading_submit: false,\n                showLeftShadow: false,\n                showRightShadow: false,\n            }\n        },\n        async mounted () {\n            let column_resource = _.split(this.resource, '/')\n            await this.$http.get(`/${_.head(column_resource)}/columns`).then((response) => {\n                this.columns = response.data\n                this.search.column = _.head(Object.keys(this.columns))\n            });\n            await this.getRecords()\n\n            this.$nextTick(() => {\n                const el = this.$refs.scrollContainer;\n                if (el) {\n                    el.addEventListener('scroll', this.checkScrollShadows);\n                    this.checkScrollShadows();\n                }\n            });\n\n        },\n        created() {\n\n            this.title = 'Series'\n\n            this.$eventHub.$on('reloadData', () => {\n                this.getRecords()\n            })\n\n        },\n        methods: { \n            checkScrollShadows() {\n                const el = this.$refs.scrollContainer;\n                if (!el) return;\n                \n                const scrollLeft = el.scrollLeft;\n                const scrollRight = el.scrollWidth - el.clientWidth - scrollLeft;\n                \n                this.showLeftShadow = scrollLeft > 1;\n                this.showRightShadow = scrollRight > 1;\n            },\n            toggleInformation() {\n                this.isVisible = !this.isVisible;\n            },\n            customIndex(index) {\n                return (this.pagination.per_page * (this.pagination.current_page - 1)) + index + 1\n            },\n            getRecords() {\n\n                this.loading_submit = true\n\n                return this.$http.get(`/${this.resource}/records?${this.getQueryParameters()}`).then((response) => {\n\n                    this.records = response.data.data\n                    this.pagination = response.data.meta\n                    this.pagination.per_page = parseInt(response.data.meta.per_page)\n\n                })\n                .catch(error => {\n                })\n                .then(() => {\n                    this.loading_submit = false\n                });\n            },\n            getQueryParameters() {\n                return queryString.stringify({\n                    page: this.pagination.current_page,\n                    limit: this.limit,\n                    ...this.search\n                })\n            },\n            changeClearInput(){\n                this.search.value = ''\n                this.getRecords()\n            },\n            clickExport(){\n\n                let query = queryString.stringify({\n                    ...this.search\n                })\n\n                window.open(`/${this.resource}/export?${query}`, '_blank');\n\n            },\n            clickCreate(recordId = null) {\n                this.recordId = recordId\n                this.showDialog = true\n            }\n        }\n    }\n</script>\n"],"sourceRoot":""}]);
