___CSS_LOADER_EXPORT___.push([module.id, "\n@media only screen and (max-width: 485px) {\n.filter-container {\n        margin-top: 0px;\n& .btn-filter-content,\n        .btn-container-mobile {\n            display: flex;\n            align-items: center;\n            justify-content: start;\n}\n}\n}\n", "",{"version":3,"sources":["webpack://./modules/Restaurant/Resources/assets/js/views/orders/index.vue"],"names":[],"mappings":";AA6SA;AACA;QACA,eAAA;AACA;;YAEA,aAAA;YACA,mBAAA;YACA,sBAAA;AACA;AACA;AACA","sourcesContent":["<template>\n    <div v-loading=\"loading_submit\">\n        <div class=\"page-header pr-0\">\n            <h2>\n                <a href=\"/restaurant/orders\">\n                    <svg\n                        xmlns=\"http://www.w3.org/2000/svg\"\n                        style=\"margin-top: -5px;\"\n                        width=\"24\"\n                        height=\"24\"\n                        viewBox=\"0 0 24 24\"\n                        fill=\"none\"\n                        stroke=\"currentColor\"\n                        stroke-width=\"2\"\n                        stroke-linecap=\"round\"\n                        stroke-linejoin=\"round\"\n                        class=\"icon icon-tabler icons-tabler-outline icon-tabler-tools-kitchen-2\"\n                    >\n                        <path stroke=\"none\" d=\"M0 0h24v24H0z\" fill=\"none\" />\n                        <path\n                            d=\"M19 3v12h-5c-.023 -3.681 .184 -7.406 5 -12zm0 12v6h-1v-3m-10 -14v17m-3 -17v3a3 3 0 1 0 6 0v-3\"\n                        />\n                    </svg>\n                </a>\n            </h2>\n            <ol class=\"breadcrumbs\">\n                <li class=\"active\">\n                    <span>Pedidos</span>\n                </li>\n            </ol>\n            <div class=\"right-wrapper pull-right\"></div>\n        </div>\n        <div class=\"card tab-content-default row-new mb-0\">\n            <!-- <div class=\"card-header bg-info\">\n        <h3 class=\"my-0\">Listado de Pedidos Restaurante</h3>\n      </div> -->\n            <div class=\"card-body\">\n                <data-table :resource=\"resource\">\n                    <tr slot=\"heading\" width=\"100%\">\n                        <!-- <th>#</th> -->\n                        <th>Codigo de Pedido</th>\n                        <th>Cliente</th>\n                        <th class=\"text-center\">Detalle Productos</th>\n                        <th class=\"text-right\">Total</th>\n                        <th>Fecha Emision</th>\n                        <th>Medio Pago</th>\n                        <th>Estatus del Pedido</th>\n                        <th class=\"text-center\">Documento</th>\n                        <th class=\"text-right\">Opciones</th>\n                    </tr>\n                    <tr></tr>\n                    <tr slot-scope=\"{ index, row }\">\n                        <!-- <td>{{ index }}</td> -->\n                        <td>{{ row.order_id }}</td>\n                        <td>{{ row.customer }}</td>\n                        <td class=\"text-center\">\n                            <template>\n                                <el-popover\n                                    placement=\"right\"\n                                    width=\"540\"\n                                    trigger=\"click\"\n                                >\n                                    <el-table\n                                        style=\"width: 100%\"\n                                        :data=\"row.items\"\n                                    >\n                                        <!--\n                      En la edicion del item, el nombre es descripcion, por ello, aqui tambien debe ser descripcion\n  <el-table-column width=\"150\" property=\"name\" label=\"Nombre\"></el-table-column>\n  @todo homologar campos en editar/crear item.\n  -->\n                                        <el-table-column\n                                            width=\"150\"\n                                            property=\"description\"\n                                            label=\"Nombre\"\n                                        ></el-table-column>\n                                        <el-table-column\n                                            width=\"90\"\n                                            property=\"cantidad\"\n                                            label=\"Cant.\"\n                                        ></el-table-column>\n                                        <el-table-column\n                                            width=\"90\"\n                                            label=\"Precio\"\n                                        >\n                                            <template slot-scope=\"scope\">\n                                                <span\n                                                    >{{\n                                                        scope.row\n                                                            .currency_type_id ===\n                                                        \"USD\"\n                                                            ? \"$\"\n                                                            : \"S/\"\n                                                    }}\n                                                    {{\n                                                        Number(\n                                                            scope.row\n                                                                .sale_unit_price\n                                                        ).toFixed(2)\n                                                    }}</span\n                                                >\n                                            </template>\n                                        </el-table-column>\n                                        <el-table-column\n                                            width=\"90\"\n                                            property=\"exchange_rate_sale\"\n                                            label=\"T/C\"\n                                        ></el-table-column>\n                                        <el-table-column\n                                            width=\"90\"\n                                            label=\"Subtotal\"\n                                        >\n                                            <template slot-scope=\"scope\">\n                                                <span\n                                                    >S/\n                                                    {{\n                                                        subtotal(scope.row)\n                                                    }}</span\n                                                >\n                                            </template>\n                                        </el-table-column>\n                                    </el-table>\n                                    <table\n                                        class=\"el-table--small el-table--fit el-table\"\n                                    >\n                                        <thead class=\"has-gutter\">\n                                            <th colspan=\"2\" class=\"text-center\">\n                                                Contacto\n                                            </th>\n                                        </thead>\n                                        <tbody>\n                                            <tr class=\"el-table tr\">\n                                                <td class=\"el-table--small td\">\n                                                    TELÉFONO:\n                                                    {{ row.customer_telefono }}\n                                                </td>\n                                            </tr>\n                                            <tr class=\"el-table tr\">\n                                                <td class=\"el-table--small td\">\n                                                    DIRECCIÓN:\n                                                    {{ row.customer_direccion }}\n                                                </td>\n                                            </tr>\n                                        </tbody>\n                                    </table>\n                                    <el-button\n                                        slot=\"reference\"\n                                        icon=\"el-icon-zoom-in\"\n                                    ></el-button>\n                                </el-popover>\n                            </template>\n                        </td>\n                        <td class=\"text-right\">S/ {{ row.total }}</td>\n                        <td>{{ formatDate(row.created_at) }}</td>\n                        <td>{{ row.reference_payment }}</td>\n                        <td>\n                            <el-select\n                                v-model=\"row.status_order_id\"\n                                placeholder=\"Estatus Pedido\"\n                                :value=\"row.status_order_id\"\n                                @change=\"updateStatus(row)\"\n                            >\n                                <el-option\n                                    v-for=\"item in options\"\n                                    :key=\"item.id\"\n                                    :label=\"item.description\"\n                                    :value=\"item.id\"\n                                ></el-option>\n                            </el-select>\n                        </td>\n                        <td class=\"text-center\">\n                            <template v-if=\"row.document_type_id == '80'\">\n                                {{ row.sale_note_number_full }}\n                            </template>\n                            <template v-else>\n                                {{ row.number_document }}\n                            </template>\n                        </td>\n                        <td class=\"text-right\">\n                            <template v-if=\"row.document_type_id == '80'\">\n                                <el-button\n                                    v-if=\"row.sale_note_id\"\n                                    class=\"submit\"\n                                    type=\"success\"\n                                    icon=\"el-icon-tickets\"\n                                    @click.prevent=\"\n                                        clickOptions(row.sale_note_id)\n                                    \"\n                                ></el-button>\n                            </template>\n                            <template v-else>\n                                <el-button\n                                    v-if=\"row.document_external_id\"\n                                    class=\"submit\"\n                                    type=\"success\"\n                                    icon=\"el-icon-tickets\"\n                                    @click.prevent=\"\n                                        clickDownload(row.document_external_id)\n                                    \"\n                                ></el-button>\n                            </template>\n                        </td>\n                    </tr>\n                </data-table>\n            </div>\n        </div>\n\n        <el-dialog\n            title=\"Stock en almacén\"\n            width=\"40%\"\n            :visible=\"showDialog\"\n            :close-on-click-modal=\"false\"\n            :close-on-press-escape=\"false\"\n            append-to-body\n            :show-close=\"false\"\n        >\n            <div class=\"form-body\">\n                <div class=\"row\">\n                    <div class=\"col-lg-12 col-md-12 table-responsive\">\n                        <table width=\"100%\" class=\"table\">\n                            <thead>\n                                <tr>\n                                    <th>Producto</th>\n                                    <th class=\"text-center\">Almacén</th>\n                                </tr>\n                            </thead>\n                            <tbody\n                                v-for=\"(rowProduct,\n                                indexProduct) in totalProduct\"\n                                :key=\"indexProduct\"\n                                width=\"100%\"\n                            >\n                                <tr>\n                                    <td>\n                                        {{ record.items[indexProduct].name }}\n                                    </td>\n                                    <td>\n                                        <el-select\n                                            v-model=\"form[rowProduct]\"\n                                            placeholder=\"Almacenes\"\n                                        >\n                                            <el-option\n                                                v-if=\"\n                                                    rowProduct === item.item_id\n                                                \"\n                                                v-for=\"item in warehouses\"\n                                                :key=\"item.id\"\n                                                :label=\"\n                                                    item.warehouse +\n                                                        ' - ' +\n                                                        'Stock -> ' +\n                                                        Math.trunc(item.stock)\n                                                \"\n                                                :value=\"item.id\"\n                                                :disabled=\"\n                                                    optionDisable(\n                                                        item.item_id,\n                                                        item.stock\n                                                    )\n                                                \"\n                                            ></el-option>\n                                        </el-select>\n                                    </td>\n                                </tr>\n                            </tbody>\n                        </table>\n                    </div>\n                </div>\n            </div>\n            <div class=\"form-actions text-right pt-2\">\n                <el-button class=\"second-buton\" @click=\"close\"\n                    >Cerrar</el-button\n                >\n                <el-button type=\"primary\" @click=\"save\">Guardar</el-button>\n            </div>\n        </el-dialog>\n\n        <options-form\n            :showDialog.sync=\"showDialogOptions\"\n            :recordId=\"documentNewId\"\n            :statusDocument=\"statusDocument\"\n            :resource=\"resource_options\"\n        ></options-form>\n\n        <document-form\n            :order_id=\"order_id\"\n            :user=\"user\"\n            :document_types=\"document_types\"\n            ref=\"document_form\"\n        >\n        </document-form>\n\n        <sale-note-form\n            :showDialog.sync=\"showDialogSaleNote\"\n            :orderId=\"order_id\"\n            :dataSaleNote=\"dataSaleNote\"\n        >\n        </sale-note-form>\n    </div>\n</template>\n<style>\n@media only screen and (max-width: 485px) {\n    .filter-container {\n        margin-top: 0px;\n        & .btn-filter-content,\n        .btn-container-mobile {\n            display: flex;\n            align-items: center;\n            justify-content: start;\n        }\n    }\n}\n</style>\n<script>\nimport DataTable from \"../../components/Datatable.vue\";\nimport OptionsForm from \"@views/pos/partials/options.vue\";\nimport DocumentForm from \"@views/orders/partials/document_form.vue\";\nimport SaleNoteForm from \"@views/orders/partials/sale_note_form.vue\";\n\nexport default {\n    props: [\"user\"],\n\n    components: { DataTable, OptionsForm, DocumentForm, SaleNoteForm },\n    data() {\n        return {\n            showDialog: false,\n            showImportDialog: false,\n            showImageDetail: false,\n            resource: \"restaurant/orders\",\n            recordId: null,\n            options: [],\n            warehouses: [],\n            estableciment_id: \"\",\n            totalProduct: [], // items_id\n            showDialog: false,\n            form: [],\n            record: \"\", // record orders\n            stocks: \"\",\n            showDialogOptions: false,\n            documentNewId: null,\n            statusDocument: {},\n            resource_options: null,\n            loading_submit: false,\n            document_types: [],\n            order_id: null,\n            dataSaleNote: {},\n            showDialogSaleNote: false\n        };\n    },\n    async created() {\n        this.$http.get(`/statusOrder/records`).then(response => {\n            this.options = response.data;\n        });\n        this.events();\n    },\n    computed: {},\n    methods: {\n        formatDate(date) {\n            if (!date) return null;\n            const parsedDate = moment(date);\n            return parsedDate.isValid()\n                ? parsedDate.format(\"DD-MM-YYYY h:mmA\")\n                : null;\n        },\n        clickOptions(recordId) {\n            this.documentNewId = recordId;\n            this.statusDocument.send = \"\";\n            this.resource_options = \"sale-notes\";\n            this.showDialogOptions = true;\n        },\n        async clickDownload(row) {\n            await this.$http\n                .get(`/documents/search/externalId/${row}`)\n                .then(response => {\n                    this.documentNewId = response.data.id;\n                });\n            this.statusDocument.send = \"\";\n            this.resource_options = \"documents\";\n            this.showDialogOptions = true;\n        },\n        subtotal(item) {\n            var subtotal;\n            if (item.currency_type_id === \"USD\") {\n                subtotal = Number(\n                    item.cantidad *\n                        item.exchange_rate_sale *\n                        parseFloat(item.sale_unit_price)\n                ).toFixed(2);\n                if (isNaN(subtotal)) {\n                    return \"-\";\n                } else {\n                    return subtotal;\n                }\n            } else {\n                return parseFloat(item.cantidad * item.sale_unit_price);\n            }\n        },\n        optionDisable(product, stock) {\n            for (var i = 0; i < this.record.items.length; i++) {\n                if (product === this.record.items[i].id) {\n                    return stock >= this.record.items[i].cantidad\n                        ? false\n                        : true;\n                }\n            }\n        },\n        openDialogSaleNote(sale_note) {\n            this.dataSaleNote = sale_note;\n            this.showDialogSaleNote = true;\n        },\n        async updateStatus(record) {\n            this.record = record;\n\n            if (record.status_order_id === 2) {\n                this.order_id = record.id;\n\n                if (record.purchase.codigo_tipo_documento == \"80\") {\n                    if (record.has_sale_note)\n                        return this.$message.success(\n                            \"Ya existe una nota de venta\"\n                        );\n                    this.openDialogSaleNote(record.purchase);\n                    // console.log(record)\n                } else {\n                    if (record.document_external_id) {\n                        return this.$message.success(\n                            \"Ya existe un comprobante.\"\n                        );\n                    }\n                    this.$refs.document_form.sendPreview(record.purchase);\n                    //this.loading_submit = true\n                    //await this.sendDocument(record.purchase)\n                }\n            } else if (record.status_order_id === 3) {\n                this.totalProduct = await this.products(record);\n                await this.$http\n                    .post(`/orders/warehouse`, { item_id: this.totalProduct })\n                    .then(response => {\n                        this.warehouses = response.data.data;\n                        this.showDialog = true;\n                    });\n                return;\n            } else {\n                this.saveUpdateStatus();\n            }\n        },\n        saveUpdateStatus() {\n            this.$http\n                .post(`/statusOrder/update`, { record: this.record })\n                .then(response => {\n                    this.$message.success(response.data.message);\n                });\n        },\n        async save() {\n            var save = [];\n\n            for (var i = 0; i < this.record.items.length; i++) {\n                if (this.totalProduct[i] === this.record.items[i].id) {\n                    save.push({\n                        id: this.form[this.totalProduct[i]],\n                        cantidad: this.record.items[i].cantidad\n                    });\n                }\n            }\n\n            await this.$http\n                .post(`/statusOrder/update`, {\n                    record: this.record,\n                    discount: save\n                })\n                .then(response => {\n                    this.$message.success(response.data.message);\n                    this.close();\n                });\n        },\n        close() {\n            this.form = [];\n            this.showDialog = false;\n            this.recoard = \"\";\n        },\n        products(products) {\n            let listProduct = [];\n\n            for (var i = 0; i <= products.items.length - 1; i++) {\n                listProduct.push(products.items[i].id);\n            }\n            return listProduct;\n        },\n        async events() {\n            await this.$eventHub.$on(\"cancelSale\", () => {\n                this.showDialogOptions = false;\n            });\n        },\n\n        getHeaderConfig() {\n            let token = this.user.api_token;\n            let httpConfig = {\n                headers: {\n                    \"Content-Type\": \"application/json\",\n                    Authorization: `Bearer ${token}`\n                }\n            };\n            return httpConfig;\n        }\n    }\n};\n</script>\n"],"sourceRoot":""}]);
