\n                        <div class=\"text-left mt-3 mb-0\">\n                            <address class=\"ib mr-2\">\n                                <span class=\"font-weight-bold d-block\"\n                                    >PEDIDO</span\n                                >\n                                <!-- <span class=\"font-weight-bold d-block\">PD-XXX</span> -->\n                                <span class=\"font-weight-bold\">{{\n                                    company.name\n                                }}</span>\n                                <br />\n                                <div v-if=\"config.establishment.address != '-'\">\n                                    {{ config.establishment.address }},\n                                </div>\n                                {{ config.establishment.district.description }},\n                                {{ config.establishment.province.description }},\n                                {{\n                                    config.establishment.department.description\n                                }}\n                                -\n                                {{ config.establishment.country.description }}\n                                <br />\n                                {{ config.establishment.email }} -\n                                <span\n                                    v-if=\"config.establishment.telephone != '-'\"\n                                    >{{ config.establishment.telephone }}</span\n                                >\n                            </address>\n                        </div>\n\n                        <div\n                            class=\"d-flex justify-content-end align-items-center dates\"\n                            style=\"margin-left: auto;\"\n                        >\n                            <div class=\"p-1 issue-date\" style=\"width: 30%;\">\n                                <div\n                                    class=\"form-group\"\n                                    :class=\"{\n                                        'has-danger': errors.date_of_issue\n                                    }\"\n                                >\n                                    <!--<label class=\"control-label\">Fecha de emisión</label>-->\n                                    <label class=\"control-label\"\n                                        >Fec. Emisión</label\n                                    >\n                                    <el-date-picker\n                                        v-model=\"form.date_of_issue\"\n                                        type=\"date\"\n                                        value-format=\"yyyy-MM-dd\"\n                                        :clearable=\"false\"\n                                        @change=\"changeDateOfIssue\"\n                                    ></el-date-picker>\n                                    <small\n                                        class=\"form-control-feedback\"\n                                        v-if=\"errors.date_of_issue\"\n                                        v-text=\"errors.date_of_issue[0]\"\n                                    ></small>\n                                </div>\n                            </div>\n                            <div\n                                class=\"p-1 expiration-date\"\n                                style=\"width: 30%;\"\n                            >\n                                <div\n                                    class=\"form-group\"\n                                    :class=\"{\n                                        'has-danger': errors.date_of_due\n                                    }\"\n                                >\n                                    <label class=\"control-label\"\n                                        >Fec. Vencimiento</label\n                                    >\n                                    <el-date-picker\n                                        v-model=\"form.date_of_due\"\n                                        type=\"date\"\n                                        value-format=\"yyyy-MM-dd\"\n                                        :clearable=\"true\"\n                                    ></el-date-picker>\n                                    <small\n                                        class=\"form-control-feedback\"\n                                        v-if=\"errors.date_of_due\"\n                                        v-text=\"errors.date_of_due[0]\"\n                                    ></small>\n                                </div>\n                            </div>\n                            <div class=\"p-1 delivery-date\" style=\"width: 30%;\">\n                                <div\n                                    class=\"form-group\"\n                                    :class=\"{\n                                        'has-danger': errors.delivery_date\n                                    }\"\n                                >\n                                    <label class=\"control-label\"\n                                        >Fec. Entrega</label\n                                    >\n                                    <el-date-picker\n                                        v-model=\"form.delivery_date\"\n                                        type=\"date\"\n                                        value-format=\"yyyy-MM-dd\"\n                                        :clearable=\"true\"\n                                    ></el-date-picker>\n                                    <small\n                                        class=\"form-control-feedback\"\n                                        v-if=\"errors.delivery_date\"\n                                        v-text=\"errors.delivery_date[0]\"\n                                    ></small>\n                                </div>\n                            </div>\n                        </div>\n                    </div>\n                </header>\n                <form autocomplete=\"off\" @submit.prevent=\"submit\">\n                    <div class=\"form-body m-4\">\n                        <div class=\"row mt-1\">\n                            <div class=\"col-lg-8 pb-2\">\n                                <div\n                                    class=\"form-group\"\n                                    :class=\"{\n                                        'has-danger': errors.customer_id\n                                    }\"\n                                >\n                                    <label\n                                        class=\"control-label font-weight-bold text-info\"\n                                    >\n                                        Cliente\n                                        <a\n                                            href=\"#\"\n                                            @click.prevent=\"\n                                                showDialogNewPerson = true\n                                            \"\n                                            >[+ Nuevo]</a\n                                        >\n                                    </label>\n                                    <el-select\n                                        v-model=\"form.customer_id\"\n                                        filterable\n                                        remote\n                                        class=\"border-left rounded-left border-info\"\n                                        popper-class=\"el-select-customers\"\n                                        dusk=\"customer_id\"\n                                        placeholder=\"Escriba el nombre o número de documento del cliente\"\n                                        :remote-method=\"searchRemoteCustomers\"\n                                        :loading=\"loading_search\"\n               