stify-content: start;\n}\n.head-notes .dates {\n        margin-left: 0px !important;\n}\n.head-notes .dates .issue-date,\n    .head-notes .dates .expiration-date,\n    .head-notes .dates .delivery-date {\n        width: 100% !important;\n}\n}\n@media only screen and (max-width: 460px) {\n.additional-information {\n        width: 80%;\n}\n.toggle-button.shift {\n        right: 58% !important;\n}\n}\n", "",{"version":3,"sources":["webpack://./modules/Sale/Resources/assets/js/views/contracts/form.vue"],"names":[],"mappings":";AAsxBA;IACA,eAAA;IACA,QAAA;IACA,aAAA;IACA,0CAAA;IACA,wBAAA;IACA,0CAAA;IACA,YAAA;IACA,iBAAA;IACA,eAAA;IACA,kBAAA;IACA,UAAA;IACA,gCAAA;IACA,gBAAA;IACA,eAAA;IACA,cAAA;IACA,cAAA;IACA,YAAA;IACA,uBAAA;IACA,YAAA;IACA,mBAAA;IACA,gBAAA;IACA,uBAAA;IACA,kBAAA;AACA;AACA;IACA,wCAAA;IACA,yCAAA;AACA;AACA;IACA,uBAAA;IACA,wCAAA;IACA,aAAA;AACA;AACA;IACA,eAAA;IACA,aAAA;IACA,sBAAA;IACA,kBAAA;IACA,mBAAA;IACA,MAAA;IACA,YAAA;IACA,YAAA;IACA,YAAA;IACA,yBAAA;IACA,yCAAA;IACA,kCAAA;IACA,gBAAA;IACA,aAAA;AACA;AACA;IACA,QAAA;AACA;AACA;IACA,kBAAA;AACA;AACA;IACA,WAAA;IACA,eAAA;IACA,MAAA;IACA,OAAA;IACA,WAAA;IACA,YAAA;IACA,oCAAA;IACA,aAAA;AACA;AACA;AACA;QACA,aAAA;QACA,sBAAA;AACA;AACA;;;QAGA,qBAAA;AACA;AACA;AACA;AACA;QACA,aAAA;QACA,sBAAA;QACA,sBAAA;AACA;AACA;QACA,2BAAA;AACA;AACA;;;QAGA,sBAAA;AACA;AACA;AACA;AACA;QACA,UAAA;AACA;AACA;QACA,qBAAA;AACA;AACA","sourcesContent":["<template>\n    <div\n        class=\"card mb-0 pt-2 pt-md-0\"\n        :class=\"{ 'content-opacity': isVisible }\"\n        @click.self=\"toggleInformation\"\n    >\n        <!-- <div class=\"card-header bg-info\">\n            <h3 class=\"my-0\">Nuevo Comprobante</h3>\n        </div> -->\n        <div\n            class=\"tab-content tab-content-default row-new\"\n            v-if=\"loading_form\"\n        >\n            <div class=\"invoice p-0\">\n                <header class=\"clearfix clearfix-default p-2\">\n                    <div class=\"d-flex head-notes\">\n                        <div\n                            class=\"col-sm-2 text-center mt-3 mb-0\"\n                            style=\"margin-right: auto;\"\n                        >\n                        <logo \n                            url=\"/\"\n                            :path_logo=\"getCurrentLogo\"\n                        ></logo>\n                        </div>\n                        <div class=\"text-left mt-3 mb-0\">\n                            <address class=\"ib mr-2\">\n                                <span class=\"font-weight-bold d-block\"\n                                    >CONTRATO</span\n                                >\n                                <!-- <span class=\"font-weight-bold d-block\">CNT-XXX</span> -->\n                                <span class=\"font-weight-bold\">{{\n                                    company.name\n                                }}</span>\n                                <br />\n                                <div v-if=\"establishment.address != '-'\">\n                                    {{ establishment.address }},\n                                </div>\n                                {{ establishment.district.description }},\n                                {{ establishment.province.description }},\n                                {{ establishment.department.description }} -\n                                {{ establishment.country.description }}\n                                <br />\n                                {{ establishment.email }} -\n                                <span v-if=\"establishment.telephone != '-'\">{{\n                                    establishment.telephone\n                                }}</span>\n                            </address>\n                        </div>\n                        <!-- <div class=\"col-sm-4\"> -->\n                        <!-- <el-checkbox class=\"mt-3\" v-model=\"form.active_terms_condition\" @change=\"changeTermsCondition\">Términos y condiciones del contrato</el-checkbox> -->\n                        <!-- </div> -->\n\n                        <div\n                            class=\"d-flex align-items-center justify-content-end dates\"\n                            style=\"margin-left: auto; width: auto;\"\n                        >\n                            <div class=\"p-1 issue-date\" style=\"width: 30%;\">\n                                <div\n                                    class=\"form-group\"\n                                    :class=\"{\n                                        'has-danger': errors.date_of_issue\n                                    }\"\n                                >\n                                    <!--<label class=\"control-label\">Fecha de emisión</label>-->\n                                    <label class=\"control-label\"\n                                        >Fec. Emisión</label\n                                    >\n                                    <el-date-picker\n                                        v-model=\"form.date_of_issue\"\n                                        type=\"date\"\n                                        value-format=\"yyyy-MM-dd\"\n                                        :clearable=\"false\"\n                                        @change=\"changeDateOfIssue\"\n                                    ></el-date-picker>\n                                    <small\n                                        class=\"form-control-feedback\"\n                                        v-if=\"errors.date_of_issue\"\n                                        v-text=\"errors.date_of_issue[0]\"\n                                    ></small>\n                                </div>\n                            </div>\n                            <div\n                                class=\"p-1 expiration-date\"\n                                style=\"width: 30%;\"\n                            >\n                                <div\n                                    class=\"form-group\"\n                                    :class=\"{\n                                        'has-danger': errors.date_of_due\n                                    }\"\n                                >\n                                    <label class=\"control-label\"\n                                        >Fec. Vencimiento</label\n                                    >\n                                    <el-date-picker\n                                        v-model=\"form.date_of_due\"\n                                        type=\"date\"\n                                        value-format=\"yyyy-MM-dd\"\n                                        :clearable=\"true\"\n                                    ></el-date-picker>\n                                    <small\n                                        class=\"form-control-feedback\"\n                                        v-if=\"errors.date_of_due\"\n                                        v-text=\"errors.date_of_due[0]\"\n                                    ></small>\n                                </div>\n                            </div>\n                            <div class=\"p-1 delivery-date\" style=\"width: 30%;\">\n                                <div\n                                    class=\"form-group\"\n                                    :class=\"{\n                                        'has-danger': errors.delivery_date\n                                    }\"\n                                >\n                                    <label class=\"control-label\"\n                                        >Fec. Entrega\n                                        <el-tooltip\n                                            class=\"item\"\n                                            effect=\"dark\"\n                                            content=\"Fecha de entrega de proyecto\"\n                                            placement=\"top-end\"\n                                        >\n                                            <i class=\"fa fa-info-circle\"></i>\n                                        </el-tooltip>\n                                    </label>\n                                    <el-date-picker\n                                        v-model=\"form.delivery_date\"\n                                        type=\"date\"\n                                        value-format=\"yyyy-MM-dd\"\n                                        :clearable=\"true\"\n                                    ></el-date-picker>\n                                    <small\n                                        class=\"form-control-feedback\"\n                                        v-if=\"errors.delivery_date\"\n                                        v-text=\"errors.delivery_date[0]\"\n                                    ></small>\n                                </div>\n                            </div>\n                        </div>\n                    </div>\n                </header>\n                <form autocomplete=\"off\" @submit.prevent=\"submit\">\n                    <div class=\"form-body m-4\">\n                        <div class=\"row mt-1\">\n                            <div class=\"col-lg-6 pb-2\">\n                                <div\n                                    class=\"form-group\"\n                                    :class=\"{\n                                        'has-danger': errors.customer_id\n                                    }\"\n                                >\n                                    <label\n                                        class=\"control-label font-weight-bold text-info\"\n                                    >\n                                        Cliente\n                                        <a\n                                            href=\"#\"\n                                            @click.prevent=\"\n                                                showDialo