<div class=\"card-header bg-info\">\n                <h3 class=\"my-0\">\n                    Listado de planes\n                </h3>\n            </div> -->\n            <div class=\"card-body\">\n                <data-table>\n                    <tr slot=\"heading\">\n                        <!-- <th>\n                            #\n                        </th> -->\n                        <th class=\"text-left\">\n                            Periodo\n                        </th>\n                        <th class=\"text-right\">\n                            Cant. Veces\n                        </th>\n                        <th class=\"text-left\">\n                            Nombre\n                        </th>\n                        <th class=\"text-left\">\n                            Descripción\n                        </th>\n                        <!--\n\n                         <th class=\"text-center\">\n                             Total\n                         </th>\n                          -->\n                        <th class=\"text-right\">\n                            Acciones\n                        </th>\n                    <tr>\n                    <tr slot-scope=\"{ index, row }\">\n                        <!-- <td>\n                            {{ index }}\n                        </td> -->\n                        <td class=\"text-left\">\n                            {{ row.period }}\n                        </td>\n                        <td class=\"text-right\">\n                            {{ row.quantity_period }}\n                        </td>\n                        <td class=\"text-left\">\n                            {{ row.name }}\n                        </td>\n                        <td class=\"text-left\">\n                            {{ row.description }}\n                        </td>\n                        <!--\n                            <td class=\"text-right\">\n                                {{ row.total }}\n                            </td>\n                        -->\n                        <td class=\"text-right\">\n                            <button\n                                class=\"btn waves-effect waves-light btn-xs btn-info\"\n                                type=\"button\"\n                                @click.prevent=\"clickShowPlan(row)\">\n                                Ver\n                            </button>\n\n                            <button\n                                v-if=\"!row.hasSuscription\"\n                                class=\"btn waves-effect waves-light btn-xs btn-danger\"\n                                type=\"button\"\n                                @click.prevent=\"clickDelete(row.id)\">\n                                Eliminar\n                            </button>\n\n                        </td>\n                    </tr>\n                </data-table>\n            </div>\n\n            <plans-form\n                :showDialog.sync=\"showDialog\"\n                @reload-data=\"sendReload\"\n            >\n            </plans-form>\n        </div>\n    </div>\n</template>\n<style>\n@media only screen and (max-width: 485px){\n    .filter-container{\n      margin-top: 0px;\n      & .btn-filter-content, .btn-container-mobile{\n        display: flex;\n        align-items: center;\n        justify-content: start;\n      }\n    }\n  }\n</style>\n<script>\nimport {mapActions, mapState} from \"vuex/dist/vuex.mjs\";\n\nimport PlansForm from './form.vue'\nimport DataTable from '../components/SuscriptionsDataTable.vue'\nimport {deletable} from '../../../../../../resources/js/mixins/deletable'\nimport {exchangeRate} from \"../../../../../../resources/js/mixins/functions\";\n\nexport default {\n    props: [\n        'configuration',\n        'date'\n    ],\n    mixins: [\n        deletable,\n        exchangeRate\n    ],\n    components: {\n        PlansForm,\n        DataTable\n    },\n    data() {\n        return {\n            showDialog: false,\n        }\n    },\n    computed: {\n        ...mapState([\n            'config',\n            'resource',\n            'form_data',\n            'exchange_rate',\n            'periods',\n            'affectation_igv_types',\n            'item_search_extra_parameters',\n            'unit_types',\n            'payment_method_types',\n        ]),\n    },\n    created() {\n        this.loadConfiguration()\n\n        this.$store.commit('setItemSearchExtraParameters', {'only_service': 1});\n\n        this.$store.commit('setConfiguration', this.configuration)\n        this.$store.commit('setResource', 'plans')\n        this.$store.commit('setFormData', {\n            periods: 'M',\n            quantity_period: 12,\n        })\n        this.searchExchangeRateByDate(this.date).then(response => {\n            this.$store.commit('setExchangeRate', response)\n            // this.form.exchange_rate_sale = this.exchange_rate\n\n        });\n        this.getCommonData();\n\n    },\n    methods: {\n        ...mapActions([\n            'loadConfiguration',\n            'clearFormData',\n        ]),\n        getCommonData() {\n            this.$http.post('CommonData', {})\n                .then((response) => {\n                    this.$store.commit('setCurrencyTypes', response.data.currency_types)\n                    this.$store.commit('setAffectationIgvTypes', response.data.affectation_igv_types)\n                    this.$store.commit('setUnitTypes', response.data.unit_types)\n                    this.$store.commit('setPaymentMethodTypes', response.data.payments_credit)\n                })\n        },\n\n\n        sendReload() {\n            this.$eventHub.$emit('reloadData')\n        },\n\n        clickShowPlan(row) {\n            this.clearFormData();\n            if (row === undefined) row = {};\n            if(row.quantity_period === undefined) row.quantity_period = 12;\n            if(row.periods === undefined) row.periods = 'M';\n\n            this.$store.commit('setFormData', row)\n            this.showDialog = true\n\n        },\n\n        clickDelete(id) {\n            this.destroy(`/suscription/${this.resource}/${id}`).then(() =>\n                this.$eventHub.$emit('reloadData')\n            )\n        }\n    }\n}\n</script>\n"],"sourceRoot":""}]);
