___CSS_LOADER_EXPORT___.push([module.id, "\n@media only screen and (max-width: 485px) {\n.filter-container {\n        margin-top: 0px;\n& .btn-filter-content,\n        .btn-container-mobile {\n            display: flex;\n            align-items: center;\n            justify-content: start;\n}\n}\n}\n", "",{"version":3,"sources":["webpack://./modules/Restaurant/Resources/assets/js/views/items/index.vue"],"names":[],"mappings":";AAwMA;AACA;QACA,eAAA;AACA;;YAEA,aAAA;YACA,mBAAA;YACA,sBAAA;AACA;AACA;AACA","sourcesContent":["<template>\n    <div style=\"width: 100%;\" class=\"mr-0\">\n        <div class=\"page-header pr-0\">\n            <h2>\n                <a href=\"/restaurant/list/items\">\n                    <svg\n                        xmlns=\"http://www.w3.org/2000/svg\"\n                        style=\"margin-top: -5px;\"\n                        width=\"24\"\n                        height=\"24\"\n                        viewBox=\"0 0 24 24\"\n                        fill=\"none\"\n                        stroke=\"currentColor\"\n                        stroke-width=\"2\"\n                        stroke-linecap=\"round\"\n                        stroke-linejoin=\"round\"\n                        class=\"icon icon-tabler icons-tabler-outline icon-tabler-tools-kitchen-2\"\n                    >\n                        <path stroke=\"none\" d=\"M0 0h24v24H0z\" fill=\"none\" />\n                        <path\n                            d=\"M19 3v12h-5c-.023 -3.681 .184 -7.406 5 -12zm0 12v6h-1v-3m-10 -14v17m-3 -17v3a3 3 0 1 0 6 0v-3\"\n                        />\n                    </svg>\n                </a>\n            </h2>\n            <ol class=\"breadcrumbs\">\n                <li class=\"active\">\n                    <span>Productos</span>\n                </li>\n            </ol>\n            <div class=\"right-wrapper pull-right\">\n                <template>\n                    <button\n                        type=\"button\"\n                        class=\"btn btn-custom btn-sm  mt-2 mr-2\"\n                        @click.prevent=\"clickImport()\"\n                    >\n                        <i class=\"fa fa-upload\"></i> Importar\n                    </button>\n                    <button\n                        type=\"button\"\n                        class=\"btn btn-custom btn-sm mt-2 mr-2\"\n                        @click.prevent=\"clickCreate()\"\n                    >\n                        <i class=\"fa fa-plus-circle\"></i> Nuevo\n                    </button>\n                </template>\n            </div>\n        </div>\n        <div class=\"card tab-content-default row-new mb-0 mx-0\">\n            <!-- <div class=\"card-header bg-info\">\n        <h3 class=\"my-0\">Listado de productos Restaurante</h3>\n      </div> -->\n            <div class=\"card-body\">\n                <data-table :resource=\"'items'\" :restaurant=\"restaurant\" :sort-field=\"sortField\" :sort-direction=\"sortDirection\" @sort-change=\"handleSortChange\">\n                    <tr slot=\"heading\" width=\"100%\" slot-scope=\"{ sort }\">\n                        <!-- <th>#</th> -->\n                        <th>Cód. Interno</th>\n                        <th>Unidad</th>\n                        <th class=\"text-center\">Imagen</th>\n                        <th>\n                            <a href=\"#\" @click.prevent=\"sort('description')\" style=\"color: inherit; text-decoration: none;\">\n                                Nombre \n                                <i class=\"fas\" :class=\"{\n                                    'fa-sort-up': sortField === 'description' && sortDirection === 'asc',\n                                    'fa-sort-down': sortField === 'description' && sortDirection === 'desc',\n                                    'fa-sort': sortField !== 'description' || \n                                              (sortField === 'description' && sortDirection === 'default')\n                                }\"></i>\n                            </a>\n                        </th>\n                        <th class=\"text-right\">P.Unitario (Venta)</th>\n                        <th class=\"text-right\">Stock General</th>\n                        <th class=\"text-left\">Categoría</th>\n                        <th class=\"text-center\">Visible en Restaurant</th>\n                        <th class=\"text-right\">Acciones</th>\n                    </tr>\n                    <tr></tr>\n                    <tr slot-scope=\"{ index, row }\">\n                        <!-- <td>{{ index }}</td> -->\n                        <td>{{ row.internal_id }}</td>\n                        <td>{{ row.unit_type_id }}</td>\n                        <td class=\"text-center\">\n                            <a @click=\"viewImages(row)\" href=\"#\">\n                                <img\n                                    :src=\"row.image_url_small\"\n                                    style=\"object-fit: contain;\"\n                                    alt\n                                    width=\"32px\"\n                                    height=\"32px\"\n                                />\n                            </a>\n                        </td>\n                        <td>{{ row.description }}</td>\n                        <td class=\"text-right\">{{ row.sale_unit_price }}</td>\n                        <td\n                            class=\"text-right\"\n                            :class=\"{\n                                'text-danger': stock(row.warehouses) <= 0\n                            }\"\n                        >\n                            {{ stock(row.warehouses) }}\n                        </td>\n                        <td class=\"text-left\">\n                            {{ row.category_description }}\n                        </td>\n                        <td class=\"text-center\">\n                            <el-checkbox\n                                size=\"medium\"\n                                @change=\"visibleRestaurant($event, row.id)\"\n                                v-model=\"row.apply_restaurant\"\n                            ></el-checkbox>\n                        </td>\n                        <td class=\"text-right\">\n                            <template>\n                                <!-- v-if=\"typeUser === 'admin'\" -->\n                                <button\n                                    type=\"button\"\n                                    class=\"btn waves-effect waves-light btn-xs btn-info\"\n                                    @click.prevent=\"clickCreate(row.id)\"\n                                >\n                                    Editar\n                                </button>\n                                <button\n                                    type=\"button\"\n                                    class=\"btn waves-effect waves-light btn-xs btn-danger\"\n                                    @click.prevent=\"clickDelete(row.id)\"\n                                >\n                                    Eliminar\n                                </button>\n                            </template>\n                        </td>\n                    </tr>\n                </data-table>\n            </div>\n\n            <items-form\n                :showDialog.sync=\"showDialog\"\n                :recordId=\"recordId\"\n            ></items-form>\n\n            <items-import :showDialog.sync=\"showImportDialog\"></items-import>\n\n            <warehouses-detail\n                :showDialog.sync=\"showWarehousesDetail\"\n                :warehouses=\"warehousesDetail\"\n            ></warehouses-detail>\n\n            <!-- <images-record :showDialog.sync=\"showImageDetail\" :recordImages=\"recordImages\"></images-record> -->\n\n            <el-dialog\n                :visible.sync=\"showImageDetail\"\n                title=\"Imagenes de Producto\"\n                width=\"50%\"\n                append-to-body\n                top=\"7vh\"\n            >\n                <div class=\"row d-flex align-items-end justify-content-end\">\n                    <div class=\"col-md-3\">\n                        <h4>Thumbs</h4>\n                        <img\n                            class=\"img-thumbnail\"\n                            :src=\"recordImages.image_url_small\"\n                            alt\n                            width=\"128\"\n                        />\n                    </div>\n                    <div class=\"col-md-4\">\n                        <h4>Para productos de Venta</h4>\n                        <img\n                            class=\"img-thumbnail\"\n                            :src=\"recordImages.image_url_medium\"\n                            alt\n                            width=\"256\"\n                        />\n                    </div>\n                    <div class=\"col-md-4\">\n                        <h4>Para Tienda</h4>\n                        <img\n                            class=\"img-thumbnail\"\n                            :src=\"recordImages.image_url\"\n                            alt\n                            width=\"512\"\n                        />\n                    </div>\n                </div>\n                <div class=\"row text-right pt-2\">\n                    <div class=\"col align-self-end\">\n                        <el-button\n                            type=\"primary\"\n                            @click=\"showImageDetail = false\"\n                            >Cerrar</el-button\n                        >\n                    </div>\n                </div>\n            </el-dialog>\n        </div>\n    </div>\n</template>\n<style>\n@media only screen and (max-width: 485px) {\n    .filter-container {\n        margin-top: 0px;\n        & .btn-filter-content,\n        .btn-container-mobile {\n            display: flex;\n            align-items: center;\n            justify-content: start;\n        }\n    }\n}\n</style>\n<script>\nimport ItemsForm from \"../../../../../../../resources/js/views/tenant/items_ecommerce/form.vue\";\nimport WarehousesDetail from \"../../../../../../../resources/js/views/tenant/items_ecommerce/partials/warehouses.vue\";\nimport ItemsImport from \"./import.vue\";\nimport DataTable from \"../../../../../../../resources/js/components/DataTable.vue\";\nimport { deletable } from \"../../../../../../../resources/js/mixins/deletable\";\n\nexport default {\n    props: [],\n    mixins: [deletable],\n    components: { ItemsForm, DataTable, WarehousesDetail, ItemsImport },\n    data() {\n        return {\n            showDialog: false,\n            showImportDialog: false,\n            showWarehousesDetail: false,\n            showImageDetail: false,\n            resource: \"restaurant\",\n            recordId: null,\n            warehousesDetail: [],\n            recordImages: {\n                image_url: \"\",\n                image_url_medium: \"\",\n                image_url_small: \"\"\n            },\n            restaurant: true,\n            sortField: localStorage.getItem('itemSortField') || 'id',\n            sortDirection: localStorage.getItem('itemSortDirection') || 'desc'\n        };\n    },\n    created() {},\n    methods: {\n        handleSortChange(sort) {\n            if (this.sortField === sort.field && this.sortDirection === 'desc' && sort.field === 'description') {\n                this.sortField = 'id';\n                this.sortDirection = 'desc';\n            } else {\n                this.sortField = sort.field;\n                this.sortDirection = sort.direction;\n            }\n\n            localStorage.setItem('itemSortField', this.sortField);\n            localStorage.setItem('itemSortDirection', this.sortDirection);\n        },\n        viewImages(row) {\n            this.recordImages.image_url = row.image_url;\n            this.recordImages.image_url_medium = row.image_url_medium;\n            this.recordImages.image_url_small = row.image_url_small;\n            this.showImageDetail = true;\n        },\n        visibleRestaurant(apply_restaurant, id) {\n            this.$http\n                .post(`/${this.resource}/items/visible`, {\n                    id,\n                    apply_restaurant\n                })\n                .then(response => {\n                    if (response.data.success) {\n                        if (apply_restaurant) {\n                            this.$message.success(response.data.message);\n                        } else {\n                            this.$message.warning(response.data.message);\n                        }\n                        this.$eventHub.$emit(\"reloadData\");\n                    } else {\n                        this.$message.error(response.data.message);\n                        this.$eventHub.$emit(\"reloadData\");\n                    }\n                })\n                .catch(error => {})\n                .then(() => {});\n        },\n        clickWarehouseDetail(warehouses) {\n            this.warehousesDetail = warehouses;\n            this.showWarehousesDetail = true;\n        },\n        clickCreate(recordId = null) {\n            this.recordId = recordId;\n            this.showDialog = true;\n        },\n        clickImport() {\n            this.showImportDialog = true;\n        },\n        clickDelete(id) {\n            this.destroy(`/items/${id}`).then(() =>\n                this.$eventHub.$emit(\"reloadData\")\n            );\n        },\n        stock(items) {\n            let stock = 0;\n            items.forEach(item => {\n                stock += parseInt(item.stock);\n            });\n            return stock;\n        }\n    }\n};\n</script>\n"],"sourceRoot":""}]);
