___CSS_LOADER_EXPORT___.push([module.id, "\n.td-btns .el-button {\n    margin-bottom: 3px;\n    margin-top: 3px;\n}\n", "",{"version":3,"sources":["webpack://./modules/DocumentaryProcedure/Resources/assets/js/views/files_simplify/Files.vue"],"names":[],"mappings":";AAi/BA;IACA,kBAAA;IACA,eAAA;AACA","sourcesContent":["<template>\n    <div>\n        <div class=\"page-header pr-0\">\n            <h2>\n                <a href=\"/documentary-procedure/files_simplify\">\n                    <svg\n                        xmlns=\"http://www.w3.org/2000/svg\"\n                        style=\"margin-top: -5px;\"\n                        width=\"24\"\n                        height=\"24\"\n                        viewBox=\"0 0 24 24\"\n                        fill=\"none\"\n                        stroke=\"currentColor\"\n                        stroke-width=\"2\"\n                        stroke-linecap=\"round\"\n                        stroke-linejoin=\"round\"\n                        class=\"feather feather-folder\"\n                    >\n                        <path\n                            d=\"M22 19a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h5l2 3h9a2 2 0 0 1 2 2z\"\n                        ></path>\n                    </svg>\n                </a>\n            </h2>\n            <ol class=\"breadcrumbs\">\n                <li class=\"active\"><span>TRAMITES</span></li>\n            </ol>\n            <div class=\"right-wrapper pull-right\">\n                <div class=\"btn-group flex-wrap\">\n                    <a\n                        :href=\"`/documentary-procedure/files_simplify/new`\"\n                        class=\"btn btn-custom btn-sm mt-2 mr-2\"\n                        type=\"button\"\n                    >\n                        <!--// @click=\"onCreate\"-->\n                        <i class=\"fa fa-plus-circle\"></i> Nuevo\n                    </a>\n                </div>\n            </div>\n        </div>\n        <div class=\"card tab-content-default row-new mb-0\">\n            <!-- <div class=\"card-header bg-info\">\n                <h3 class=\"my-0\">Todos los tramites</h3>\n            </div> -->\n            <div class=\"card-body\">\n                <div class=\"btn-filter-content mb-3\">\n                    <el-button\n                        type=\"secondary\"\n                        class=\"btn-show-filter\"\n                        :class=\"{ shift: isVisible }\"\n                        @click=\"toggleInformation\"\n                    >\n                        {{ isVisible ? \"Ocultar filtros\" : \"Mostrar filtros\" }}\n                    </el-button>\n                </div>\n                <form class=\"row\" @submit.prevent=\"onFilter\" v-if=\"isVisible\">\n                    <div class=\"col-6 col-md-4 mb-3\">\n                        <el-select\n                            v-model=\"filter.person_id\"\n                            :loading=\"loading\"\n                            :remote-method=\"searchRemoteCustomers\"\n                            class=\"border-left rounded-left border-info\"\n                            filterable\n                            placeholder=\"Escriba el nombre o número de documento del cliente\"\n                            popper-class=\"el-select-customers\"\n                            remote\n                            @change=\"changeCustomer\"\n                        >\n                            <el-option\n                                v-for=\"option in customers\"\n                                :key=\"option.id\"\n                                :label=\"option.description\"\n                                :value=\"option.id\"\n                            ></el-option>\n                        </el-select>\n                    </div>\n\n                    <div class=\"col-6 col-md-4 mb-3\">\n                        <el-input\n                            v-model=\"filter.invoice\"\n                            placeholder=\"Número de expediente\"\n                            type=\"text\"\n                        />\n                    </div>\n                    <div class=\"col-6 col-md-4 mb-3\">\n                        <el-input\n                            v-model=\"filter.guide\"\n                            placeholder=\"Número de seguimiento\"\n                            type=\"text\"\n                        />\n                    </div>\n\n                    <div class=\"col-6 col-md-4 mb-3\">\n                        <el-select\n                            v-model=\"filter.documentary_guides_number_status_id\"\n                            clearable\n                            filterable\n                            placeholder=\"Estado de tramite\"\n                        >\n                            <el-option\n                                v-for=\"of in statusDocumentary\"\n                                :key=\"of.id\"\n                                :label=\"of.name\"\n                                :value=\"of.id\"\n                            ></el-option>\n                        </el-select>\n                    </div>\n                    <div class=\"col-6 col-md-4 mb-3\">\n                        <el-select\n                            v-model=\"filter.documentary_office_id\"\n                            clearable\n                            filterable\n                            placeholder=\"Etapa\"\n                        >\n                            <el-option\n                                v-for=\"of in offices\"\n                                :key=\"of.id\"\n                                :disabed=\"!of.active\"\n                                :label=\"of.name\"\n                                :value=\"of.id\"\n                            ></el-option>\n                        </el-select>\n                    </div>\n                    <div class=\"col-6 col-md-4 mb-3\">\n                        <el-select\n                            v-model=\"filter.register_date\"\n                            clearable\n                            filterable\n                            placeholder=\"Fecha de registro\"\n                            @change=\"onPrepareFilterDate\"\n                        >\n                            <el-option\n                                v-for=\"(date, i) in datesFilter\"\n                                :key=\"i\"\n                                :label=\"date\"\n                                :value=\"date\"\n                            ></el-option>\n                        </el-select>\n                    </div>\n                    <div\n                        v-if=\"filter.register_date === 'Personalizado'\"\n                        class=\"col-6 col-md-4 mb-3\"\n                    >\n                        <el-date-picker\n                            v-model=\"filter.date_start\"\n                            format=\"yyyy/MM/dd\"\n                            placeholder=\"Fecha inicial\"\n                            type=\"date\"\n                            value-format=\"yyyy-MM-dd\"\n                        >\n                        </el-date-picker>\n                    </div>\n                    <div\n                        v-if=\"filter.register_date === 'Personalizado'\"\n                        class=\"col-6 col-md-4 mb-3\"\n                    >\n                        <el-date-picker\n                            v-model=\"filter.date_end\"\n                            format=\"yyyy/MM/dd\"\n                            placeholder=\"Fecha final\"\n                            type=\"date\"\n                            value-format=\"yyyy-MM-dd\"\n                        >\n                        </el-date-picker>\n                    </div>\n                    <div class=\"col-6 col-md-4 mb-3\">\n                        <label class=\"control-label\">\n                            Archivados\n                        </label>\n                        <div class=\"form-group\">\n                            <el-switch\n                                v-model=\"filter.archived\"\n                                active-text=\"Si\"\n                                inactive-text=\"No\"\n                                @change=\"onFilter\"\n                            ></el-switch>\n                        </div>\n                    </div>\n                    <div class=\"col-6 col-md-4 mb-3\">\n                        <label class=\"control-label\">\n                            Vencidos\n                        </label>\n                        <div class=\"form-group\">\n                            <el-switch\n                                v-model=\"filter.expired\"\n                                active-text=\"Si\"\n                                inactive-text=\"No\"\n                                @change=\"onFilter\"\n                            ></el-switch>\n                        </div>\n                    </div>\n                    <!--\n                    <div class=\"col-6 col-md-4 mb-3\">\n                        <el-button native-type=\"submit\">\n                            <i class=\"fa fa-search\"></i>\n                            <span class=\"ml-2\">Buscar</span>\n                        </el-button>\n                    </div> -->\n                    <div class=\"col-12 col-md-12\">&nbsp;</div>\n                    <div\n                        class=\"col-lg-7 col-md-7 col-md-7 col-sm-12\"\n                        style=\"margin-top:29px\"\n                    >\n                        <el-button\n                            class=\"submit\"\n                            icon=\"el-icon-search\"\n                            native-type=\"submit\"\n                            type=\"primary\"\n                            >Buscar\n                        </el-button>\n\n                        <template v-if=\"items.length > 0\">\n                            <el-button\n                                class=\"submit\"\n                                type=\"success\"\n                                @click.prevent=\"clickDownload('excel')\"\n                                ><i class=\"fa fa-file-excel\"></i> Exporta Excel\n                            </el-button>\n                            <el-button\n                                class=\"submit\"\n                                icon=\"el-icon-tickets\"\n                                type=\"danger\"\n                                @click.prevent=\"clickDownload('pdf')\"\n                                >Exportar PDF\n                            </el-button>\n                        </template>\n                    </div>\n                </form>\n                <div class=\"col-md-12\">\n                <div class=\"scroll-shadow shadow-left\" v-show=\"showLeftShadow\"></div>\n                <div class=\"scroll-shadow shadow-right\" v-show=\"showRightShadow\"></div>\n                <div class=\"table-responsive\" ref=\"scrollContainer\">\n                    <table class=\"table\">\n                        <thead>\n                            <tr>\n                                <!-- <th>#</th> -->\n                                <th>Numero de expediente</th>\n                                <th>Trámite</th>\n                                <th>Cliente</th>\n                                <th>Fecha/Hora registro</th>\n                                <!--                            <th>Datos del cliente</th>-->\n                                <th class=\"text-right\">\n                                    Ultimo número de seguimiento\n                                </th>\n                                <th>Etapa</th>\n                                <th>Status de Etapa</th>\n                                <th>Fecha de fin</th>\n                                <th></th>\n                            </tr>\n                        </thead>\n                        <tbody>\n                            <tr v-for=\"(item, index) in items\" :key=\"item.id\">\n                                <!-- <td class=\"text-right\">{{ index + 1 }}</td> -->\n                                <td>\n                                    {{ item.invoice }}\n                                    <template\n                                        v-if=\"\n                                            item.is_archive && item.observation\n                                        \"\n                                    >\n                                        <br />\n                                        Motivo: {{ item.observation }}\n                                    </template>\n                                </td>\n                                <td>\n                                    <!-- requisitos -->\n                                    <el-tooltip\n                                        v-if=\"\n                                            item &&\n                                                item.documentary_process &&\n                                                item.documentary_process\n                                                    .requirements &&\n                                                item.documentary_process\n                                                    .requirements.length > 0\n                                        \"\n                                        placement=\"right-start\"\n                                    >\n                                        <div slot=\"content\">\n                                            Requisitos:\n                                            <ul\n                                                v-for=\"requirement in item\n                                                    .documentary_process\n                                                    .requirements\"\n                                            >\n                                                <li\n                                                    v-if=\"\n                                                        requirement\n                                                            .requirement_name\n                                                            .length > 0\n                                                    \"\n                                                >\n                                                    {{\n                                                        requirement.requirement_name\n                                                    }}\n                                                </li>\n                                            </ul>\n                                        </div>\n                                        <i class=\"fa fa-info-circle\"></i>\n                                    </el-tooltip>\n\n                                    <span\n                                        v-if=\"\n                                            item.documentary_process !==\n                                                undefined &&\n                                                item.documentary_process\n                                                    .name !== undefined\n                                        \"\n                                    >\n                                        {{ item.documentary_process.name }}\n                                    </span>\n\n                                    <!-- terminos y condiciones -->\n                                    <el-tooltip\n                                        v-if=\"\n                                            item &&\n                                                item.documentary_process &&\n                                                item.documentary_process\n                                                    .documentary_terms &&\n                                                item.documentary_process\n                                                    .documentary_terms.length >\n                                                    0\n                                        \"\n                                        placement=\"right-start\"\n                                    >\n                                        <div slot=\"content\">\n                                            Términos y condiciones:\n                                            <ul\n                                                v-for=\"requirement in item\n                                                    .documentary_process\n                                                    .documentary_terms\"\n                                            >\n                                                <li>\n                                                    {{ requirement.term_name }}\n                                                </li>\n                                            </ul>\n                                        </div>\n                                        <i class=\"fa fa-text-width \"></i>\n                                    </el-tooltip>\n                                </td>\n                                <td>\n                                    <span\n                                        v-if=\"\n                                            item.person !== undefined &&\n                                                item.person.description !==\n                                                    undefined\n                                        \"\n                                    >\n                                        {{ item.person.description }}\n                                    </span>\n                                </td>\n                                <td>\n                                    {{ formatDateTime(item.datetime_register) }}\n                                </td>\n                                <!--                            <td>{{ item.sender.name }}</td>-->\n                                <td class=\"text-right\">\n                                    {{\n                                        item.last_guide && item.last_guide.guide\n                                            ? item.last_guide.guide\n                                            : \"\"\n                                    }}\n                                </td>\n                                <td>\n                                    <div\n                                        v-if=\"\n                                            item.last_guide &&\n                                                item.last_guide.doc_office &&\n                                                item.last_guide.doc_office.name\n                                        \"\n                                        :style=\"\n                                            'background-color:' +\n                                                item.last_guide.doc_office\n                                                    .color +\n                                                ';font-size: 12px;'\n                                        \"\n                                        class=\"badge pl-0 text-left\"\n                                    >\n                                        {{ item.last_guide.doc_office.name }}\n                                    </div>\n                                </td>\n                                <td>\n                                    <div\n                                        v-if=\"\n                                            item.last_guide_status &&\n                                                item.last_guide_status.name\n                                        \"\n                                        :style=\"\n                                            'background-color:' +\n                                                item.last_guide_status.color +\n                                                ';font-size: 12px;'\n                                        \"\n                                        class=\"badge\"\n                                    >\n                                        {{ item.last_guide_status.name }}\n                                    </div>\n                                </td>\n                                <td>\n                                    <div\n                                        v-if=\"\n                                            item &&\n                                                item.last_guide &&\n                                                item.last_guide.date_end\n                                        \"\n                                        :class=\"item.last_guide.class\"\n                                    >\n                                        {{\n                                            formatDateTime(\n                                                item.last_guide.date_end\n                                            )\n                                        }}\n                                        <br />\n                                        <strong>\n                                            {{\n                                                getDiffDay(\n                                                    item.last_guide.date_end\n                                                )\n                                            }}\n                                        </strong>\n                                    </div>\n                                </td>\n                                <td class=\"text-center td-btns\">\n                                    <div class=\"dropdown\">\n                                        <button\n                                            id=\"dropdownMenuButton\"\n                                            aria-expanded=\"false\"\n                                            aria-haspopup=\"true\"\n                                            class=\"btn btn-default btn-sm btn-dropdown-toggle\"\n                                            data-toggle=\"dropdown\"\n                                            type=\"button\"\n                                        >\n                                            <i class=\"fas fa-ellipsis-v\"></i>\n                                            <i class=\"fas fa-ellipsis-h\" style=\"display: none;\"></i>\n                                        </button>\n                                        <div\n                                            aria-labelledby=\"dropdownMenuButton\"\n                                            class=\"dropdown-menu\"\n                                        >\n                                            <template v-if=\"!item.is_archive\">\n                                                <button\n                                                    class=\"dropdown-item\"\n                                                    type=\"button\"\n                                                    @click.prevent=\"\n                                                        editItem(item.id)\n                                                    \"\n                                                >\n                                                    Editar/Ver\n                                                </button>\n                                                <button\n                                                    class=\"dropdown-item\"\n                                                    type=\"button\"\n                                                    @click.prevent=\"\n                                                        printFile(item.id)\n                                                    \"\n                                                >\n                                                    Imprimir\n                                                </button>\n                                                <button\n                                                    v-if=\"!item.is_completed\"\n                                                    class=\"dropdown-item\"\n                                                    type=\"button\"\n                                                    @click.prevent=\"\n                                                        removeItem(item.id)\n                                                    \"\n                                                >\n                                                    Eliminar\n                                                </button>\n                                                <button\n                                                    v-if=\"!item.is_completed\"\n                                                    class=\"dropdown-item\"\n                                                    type=\"button\"\n                                                    @click.prevent=\"\n                                                        completeItem(item.id)\n                                                    \"\n                                                >\n                                                    Finalizar\n                                                </button>\n                                                <button\n                                                    class=\"dropdown-item\"\n                                                    type=\"button\"\n                                                    @click.prevent=\"\n                                                        archiveFile(item.id)\n                                                    \"\n                                                >\n                                                    Archivar\n                                                </button>\n                                            </template>\n                                            <template v-else>\n                                                <button\n                                                    class=\"dropdown-item\"\n                                                    type=\"button\"\n                                                    @click.prevent=\"\n                                                        reactiveFile(item.id)\n                                                    \"\n                                                >\n                                                    Retomar Tramite\n                                                </button>\n                                            </template>\n                                        </div>\n                                    </div>\n\n                                    <!--\n                                AGREGAR SECUENCIA DE TRAMITE <br>\n                                IMPRIMIR ESTADO DE TRAMITE<br>\n                                --></td>\n                            </tr>\n                        </tbody>\n                    </table>\n                </div>\n                </div>                \n            </div>\n        </div>\n        <ModalAddReason\n            :visible.sync=\"openModalReason\"\n            :id=\"temp_id\"\n            @addArchive=\"onArchive\"\n        ></ModalAddReason>\n        <!--\n\n        <ModalAddEdit\n            :visible.sync=\"openModalAddEdit\"\n            @onAddItem=\"onAddItem\"\n            @onUpdateItem=\"onUpdateItem\"\n            @onUploadComplete=\"onUploadComplete\"\n        ></ModalAddEdit>\n        <ModalDerive\n            :file=\"file\"\n            :visible.sync=\"showModalDerive\"\n            @onAddOffice=\"onAddOffice\"\n        ></ModalDerive>\n        <ModalStage\n            :visible.sync=\"showModalStage\"\n            @onBackStep=\"onBackStep\"\n            @onNextStep=\"onNextStep\"\n            @updateFiles=\"updateFiles\"\n        ></ModalStage>\n        <StageModalObservationStage\n            :visible.sync=\"showStageModalObservationStage\"\n        ></StageModalObservationStage>\n        -->\n    </div>\n</template>\n\n<script>\nimport ModalAddReason from \"./ModalAddReason\";\n\n/*\nimport ModalAddEdit from \"./ModalAddEdit\";\nimport ModalDerive from \"./ModalDerive\";\nimport StageModalObservationStage from \"./ModalHistoricalObservation\";\nimport ModalStage from \"./ModalStage\";\n*/\nimport moment from \"moment\";\nimport queryString from \"query-string\";\n\nimport { mapActions, mapState } from \"vuex\";\n\nexport default {\n    props: {\n        local_files: {\n            type: Array,\n            required: true\n        },\n        local_offices: {\n            type: Array,\n            required: true\n        },\n        local_processes: {\n            type: Array,\n            required: false\n        },\n        local_actions: {\n            type: Array,\n            required: false\n        },\n        local_customers: {\n            type: Array,\n            required: false\n        },\n        local_documentTypes: {\n            type: Array,\n            required: false\n        },\n        local_statusDocumentary: {\n            type: Array,\n            required: false\n        }\n    },\n    computed: {\n        ...mapState([\n            \"offices\",\n            \"file\",\n            \"files\",\n            \"processes\",\n            \"actions\",\n            \"customers\",\n            \"documentTypes\",\n            \"statusDocumentary\"\n        ])\n    },\n    components: {\n        ModalAddReason\n        /*\n        ModalAddEdit,\n        ModalDerive,\n        StageModalObservationStage,\n        ModalStage,\n        */\n    },\n    data() {\n        return {\n            isVisible: false,\n            showModalDerive: false,\n            showModalStage: false,\n            showStageModalObservationStage: false,\n            items: [],\n            openModalAddEdit: false,\n            temp_id: 0,\n            openModalReason: false,\n            loading: false,\n            filter: {\n                archived: 0,\n                expired: 0,\n                name: \"\",\n                register_date: \"Hoy\"\n            },\n            basePath: \"/documentary-procedure/files\",\n            datesFilter: [\n                \"Hoy\",\n                \"Ayer\",\n                \"Anteriores a 7 días\",\n                \"Anteriores a 30 días\",\n                \"Este mes\",\n                \"Mes anterior\",\n                \"Este año\",\n                \"Personalizado\"\n            ],\n            showLeftShadow: false,\n            showRightShadow: false,\n        };\n    },\n    created() {\n        this.loadOffices();\n        this.loadActions();\n        this.loadCustomers();\n        this.loadProcesses();\n        this.loadFiles();\n        this.loadDocumentTypes();\n    },\n    mounted() {\n        this.$store.commit(\"setOffices\", this.local_offices);\n        this.$store.commit(\"setFiles\", this.local_files);\n        this.$store.commit(\"setProcesses\", this.local_processes);\n        this.$store.commit(\"setActions\", this.local_actions);\n        this.$store.commit(\"setCustomers\", this.local_customers);\n        this.$store.commit(\"setDocumentTypes\", this.local_documentTypes);\n        this.$store.commit(\n            \"setStatusDocumentary\",\n            this.local_statusDocumentary\n        );\n\n        this.items = this.files;\n\n        this.$nextTick(() => {\n            const el = this.$refs.scrollContainer;\n            if (el) {\n                el.addEventListener('scroll', this.checkScrollShadows);\n                this.checkScrollShadows();\n            }\n        });\n    },\n    methods: {\n        checkScrollShadows() {\n            const el = this.$refs.scrollContainer;\n            if (!el) return;\n            \n            const scrollLeft = el.scrollLeft;\n            const scrollRight = el.scrollWidth - el.clientWidth - scrollLeft;\n            \n            this.showLeftShadow = scrollLeft > 1;\n            this.showRightShadow = scrollRight > 1;\n        },\n        formatDateTime(dateTime) {\n            if (!dateTime) return null;\n            const parsedDate = moment(dateTime, \"YYYY-MM-DD - HH:mm:ss\");\n            return parsedDate.isValid()\n                ? parsedDate.format(\"DD-MM-YYYY h:mmA\")\n                : null;\n        },\n        toggleInformation() {\n            this.isVisible = !this.isVisible;\n        },\n        ...mapActions([\n            \"loadOffices\",\n            \"loadActions\",\n            \"loadCustomers\",\n            \"loadProcesses\",\n            \"loadDocumentTypes\",\n            \"loadFiles\"\n        ]),\n        haveStage(item) {\n            if (item === null) return false;\n            if (item === undefined) return false;\n            if (item.observations === undefined) return false;\n            if (item.observations == null) return false;\n            if (item.observations.length == null) return false;\n            if (item.observations.length < 1) return false;\n            return true;\n        },\n        showDocument(item) {\n            item.disable = true;\n            this.$store.commit(\"setFile\", item);\n            this.$store.commit(\"setOffices\", this.offices);\n            this.openModalAddEdit = true;\n        },\n        onShowExtraButtons(file) {\n            if (file.offices) {\n                if (file.offices.length > 0) {\n                    return false;\n                }\n            }\n            return true;\n        },\n        onNextStep(office) {\n            this.updateFiles();\n        },\n        onBackStep(office) {\n            this.updateFiles();\n        },\n        updateFiles() {\n            this.loading = true;\n            this.$http\n                .post(`/documentary-procedure/file/reload`, this.filter)\n                .then(result => {\n                    let files = result.data.data;\n                    this.$store.commit(\"setFiles\", files);\n                    this.items = this.files;\n                    this.loading = false;\n                })\n                .catch(err => {\n                    this.loading = false;\n                });\n        },\n        onAddOffice(office) {\n            this.items = this.items.map(i => {\n                if (i.id === this.file.id) {\n                    i.offices.push(office);\n                }\n                return i;\n            });\n        },\n        onShowModalDerive(file) {\n            this.file = file;\n            this.showModalDerive = true;\n        },\n        onShowModalStage(file) {\n            //this.file = file;\n            this.$store.commit(\"setFile\", file);\n            this.showModalStage = true;\n        },\n        onPrepareFilterDate() {\n            const date = moment();\n            this.filter.simplify = 1;\n\n            if (this.filter.register_date === \"Hoy\") {\n                this.filter.date_start = date.format(\"YYYY-MM-DD\");\n                this.filter.date_end = null;\n            }\n            if (this.filter.register_date === \"Ayer\") {\n                this.filter.date_start = date\n                    .subtract(1, \"days\")\n                    .format(\"YYYY-MM-DD\");\n                this.filter.date_end = null;\n            }\n            if (this.filter.register_date === \"Anteriores a 7 días\") {\n                this.filter.date_start = date\n                    .subtract(7, \"days\")\n                    .format(\"YYYY-MM-DD\");\n                this.filter.date_end = moment().format(\"YYYY-MM-DD\");\n            }\n            if (this.filter.register_date === \"Anteriores a 30 días\") {\n                this.filter.date_start = date\n                    .subtract(30, \"days\")\n                    .format(\"YYYY-MM-DD\");\n                this.filter.date_end = moment().format(\"YYYY-MM-DD\");\n            }\n            if (this.filter.register_date === \"Este mes\") {\n                this.filter.date_start = date\n                    .startOf(\"month\")\n                    .format(\"YYYY-MM-DD\");\n                this.filter.date_end = date.endOf(\"month\").format(\"YYYY-MM-DD\");\n            }\n            if (this.filter.register_date === \"Mes anterior\") {\n                const prevMonth = date.subtract(1, \"month\");\n                this.filter.date_start = prevMonth\n                    .startOf(\"month\")\n                    .format(\"YYYY-MM-DD\");\n                this.filter.date_end = prevMonth\n                    .endOf(\"month\")\n                    .format(\"YYYY-MM-DD\");\n            }\n            if (this.filter.register_date === \"Este año\") {\n                this.filter.date_start = date\n                    .startOf(\"year\")\n                    .format(\"YYYY-MM-DD\");\n                this.filter.date_end = date.endOf(\"year\").format(\"YYYY-MM-DD\");\n            }\n            if (this.filter.register_date === \"Personalizado\") {\n                this.showCalendars = true;\n            }\n        },\n        onFilter() {\n            this.updateFiles();\n        },\n        onDelete(item) {\n            this.loading = true;\n            this.$confirm(\n                `¿estás seguro de eliminar al elemento ${item.invoice}?`,\n                \"Atención\",\n                {\n                    confirmButtonText: \"Si, continuar\",\n                    cancelButtonText: \"No, cerrar\",\n                    type: \"warning\"\n                }\n            )\n                .then(() => {\n                    this.updateFiles();\n                    /*\n                    this.$http\n                        .delete(`${this.basePath}/${item.id}/delete`)\n                        .then((response) => {\n                            this.$message({\n                                type: \"success\",\n                                message: response.data.message,\n                            });\n\n             