lass=\"form-group\" :class=\"{'has-danger': errors.telefono}\">\n                      <label class=\"control-label\">Telefono</label>\n                      <el-input v-model=\"row.telefono\"></el-input>\n                      <small class=\"form-control-feedback\" v-if=\"errors.telefono\" v-text=\"errors.telefono[0]\"></small>\n                    </div>\n                  </div>\n                  <div class=\"col-md-6\">\n                    <div class=\"form-group\" :class=\"{'has-danger': errors.email}\">\n                      <label class=\"control-label\">Email</label>\n                      <el-input v-model=\"row.email\"></el-input>\n                      <small class=\"form-control-feedback\" v-if=\"errors.email\" v-text=\"errors.email[0]\"></small>\n                    </div>\n                  </div>\n                </div>\n\n\n\n            </div>\n            <div class=\"form-actions text-right pt-2\">\n                <el-button class=\"second-buton\" @click.prevent=\"handleCloseDialog()\">Cancelar</el-button>\n                <el-button type=\"primary\" native-type=\"submit\" :loading=\"loading_submit\">Guardar</el-button>\n            </div>\n        </form>\n    </el-dialog>\n</template>\n\n<script>\n\n\n    export default {\n        props: ['showDialog', 'recordId', 'context', 'empresaId', 'empresaEntity'],\n        data() {\n            return {\n                loading_submit: false,\n                titleDialog: null,\n                resource: 'comercial/contactos',\n                errors: {},\n                form: {},\n                headers: headers_token,\n                list_empresas: [],\n                list_estados_interno: [],\n                loading: false,\n                searchTimeout: null,\n                lastSearch: '',\n                isInitialized: false\n            }\n        },\n        async created() {\n          await this.$http.get(`/${this.resource}/tables`)\n            .then(response => {\n              this.list_empresas = response.data.list_empresas\n              this.list_estados_interno = response.data.list_estados_interno\n            })\n\n          if (this.showDialog) {\n            if (this.recordId) {\n              // Modo edición\n              this.titleDialog = 'Editar Contacto';\n              this.$nextTick(() => {\n                this.loadContactData();\n              });\n            } else {\n              // Modo creación\n              this.titleDialog = 'Nuevo Contacto';\n              this.initForm();\n\n              // Pre-cargar empresa si existe\n              if (this.empresaEntity && this.empresaEntity.id) {\n                this.$nextTick(() => {\n                  this.$nextTick(() => {\n                    this.preloadEmpresa();\n                  });\n                });\n              }\n            }\n\n            this.isInitialized = true;\n          }\n        },\n        watch: {\n          recordId: {\n            immediate: true,\n            handler(newVal, oldVal) {\n              // Solo cargar si el diálogo está visible y hay un recordId válido\n              if (this.showDialog && newVal && newVal !== oldVal) {\n                this.$nextTick(() => {\n                  this.loadContactData();\n                });\n              }\n            }\n          },\n          showDialog: {\n            immediate: false,\n            handler(newVal, oldVal) {\n              if (newVal && !oldVal) {\n                if (this.recordId) {\n                  this.titleDialog = 'Editar Contacto';\n                  this.$nextTick(() => {\n                    this.loadContactData();\n                  });\n                } else {\n                  // Modo creación\n                  this.titleDialog = 'Nuevo Contacto';\n                  this.initForm();\n\n                  // Pre-cargar empresa si existe\n                  if (this.empresaEntity && this.empresaEntity.id) {\n                    // Usar múltiples nextTick para asegurar que el DOM esté listo\n                    this.$nextTick(() => {\n                      this.$nextTick(() => {\n                        this.preloadEmpresa();\n                      });\n                    });\n                  }\n                }\n\n                this.isInitialized = true;\n              } else if (!newVal && oldVal) {\n                // El diálogo se acaba de cerrar\n                this.isInitialized = false;\n              }\n            }\n          },\n          // Agregar watcher para empresaEntity\n          empresaEntity: {\n            deep: true,\n            handler(newVal, oldVal) {\n              // Si el diálogo está abierto, no hay recordId (nuevo contacto) y hay una empresa\n              if (this.showDialog && !this.recordId && newVal && newVal.id) {\n                this.$nextTick(() => {\n                  this.preloadEmpresa();\n                });\n              }\n            }\n          }\n        },\n        methods: {\n            onOpen() {\n              // Si ya está inicializado por los watchers, no hacer nada\n              if (this.isInitialized) {\n                return;\n              }\n\n              this.errors = {};\n\n              if (this.recordId) {\n                this.titleDialog = 'Editar Contacto';\n                this.$nextTick(() => {\n                  this.loadContactData();\n                });\n              } else {\n                this.titleDialog = 'Nuevo Contacto';\n                this.initForm();\n\n                if (this.empresaEntity && this.empresaEntity.id) {\n                  this.$nextTick(() => {\n                    this.preloadEmpresa();\n                  });\n                }\n              }\n\n              this.isInitialized = true;\n            },\n            preloadEmpresa() {\n              if (!this.empresaEntity || !this.empresaEntity.id) {\n                return;\n              }\n\n              // Extraer datos de la empresa (manejar Getters & Setters de Vue)\n              const empresaId = parseInt(this.empresaEntity.id);\n              const empresaRazon = this.empresaEntity.razon_social || this.empresaEntity.nombre_comercial || 'Empresa';\n\n              const empresaToAdd = {\n                id: empresaId,\n                razon_social: empresaRazon\n              };\n\n              // Buscar si ya existe en la lista\n              const existsIndex = this.list_empresas.findIndex(e => e.id === empresaId);\n\n              if (existsIndex === -1) {\n                this.list_empresas.unshift(empresaToAdd);\n              } else {\n                this.$set(this.list_empresas, existsIndex, empresaToAdd);\n              }\n\n              // Asignar el ID al formulario\n              this.form.empresa_id = empresaId;\n\n              // Forzar actualización del componente\n              this.$forceUpdate();\n\n              this.$nextTick(() => {\n                this.originalForm = JSON.stringify(this.form);\n              });\n            },\n\n            loadContactData() {\n              this.loading = true;\n              this.$http.get(`/${this.resource}/record/${this.recordId}`)\n                .then(response => {\n                  const data = response.data.data;\n\n                  // Validar que data existe\n                  if (!data) {\n                    this.$message.error('No se pudieron cargar los datos del contacto');\n                    this.forceCloseDialog();\n                    return;\n                  }\n\n                  // Asignar todos los campos del formulario\n                  this.form = {\n                    id: data.id,\n                    empresa_id: data.empresa_id,\n                    nombres: data.nombres,\n                    apellidos: data.apellidos,\n                    cargo: data.cargo,\n                    celular: data.celular,\n                    estado: Number(data.estado),\n                    origen: data.origen,\n                    tipo_contacto: data.tipo_contacto,\n                    fecha_cumpleanos: data.fecha_cumpleanos,\n                    direccion: data.direccion,\n                    emails: Array.isArray(data.emails) ? data.emails : [],\n                    telefono: data.telefono,\n                    email: data.email,\n                  };\n\n                  // Manejar la empresa en el select\n                  if (data.empresa_id) {\n                    let empresaNombre = 'Empresa';\n\n                    // Intentar obtener el nombre de la empresa de diferentes formas\n                    if (data.empresa) {\n                      // Si viene como objeto\n                      empresaNombre = data.empresa.razon_social || data.empresa.nombre_comercial || 'Empresa';\n                    } else if (data.razon_social_empresa) {\n                      // Si viene como campo directo\n                      empresaNombre = data.razon_social_empresa;\n                    }\n\n                    // Verificar si la empresa ya está en la lista\n                    const empresaExiste = this.list_empresas.find(e => e.id === data.empresa_id);\n\n                    if (!empresaExiste) {\n                      this.list_empresas.unshift({\n                        id: data.empresa_id,\n                        razon_social: empresaNombre\n                      });\n                    }\n                  }\n\n                  // Guardar estado original del formulario\n                  this.$nextTick(() => {\n                    this.originalForm = JSON.stringify(this.form);\n                  });\n                })\n                .catch(error => {\n                  this.$message.error('No se pudo cargar el registro para editar');\n                  this.forceCloseDialog();\n                })\n                .finally(() => {\n                  this.loading = false;\n                });\n            },\n            handleCloseDialog() {\n              if (this.hasUnsavedChanges()) {\n                this.$confirm('¿Estás seguro de cerrar el formulario? Se perderán los datos no guardados.', 'Confirmar', {\n                  confirmButtonText: 'Cerrar sin guardar',\n                  cancelButtonText: 'Cancelar',\n                  type: 'warning'\n                }).then(() => {\n                  this.forceCloseDialog()\n                }).catch(() => {\n\n                });\n              } else {\n                this.forceCloseDialog()\n              }\n            },\n            forceCloseDialog() {\n              this.initForm()\n              this.isInitialized = false\n              this.$emit('update:showDialog', false)\n              this.$emit('update:recordId', null)\n            },\n            hasUnsavedChanges() {\n                return JSON.stringify(this.form) !== this.originalForm\n            },\n            async getEmpresas(query) {\n              if (query === this.lastSearch) return;\n\n              if (!query || query.length < 3) {\n                // No limpiar la lista si hay una empresa pre-cargada\n                if (!this.form.empresa_id) {\n                  this.list_empresas = [];\n                }\n                this.lastSearch = query;\n                return;\n              }\n\n              // Debounce\n              if (this.searchTimeout) {\n                clearTimeout(this.searchTimeout);\n              }\n\n              this.searchTimeout = setTimeout(async () => {\n                this.loading = true;\n                this.lastSearch = query;\n\n                try {\n                  const response = await this.$http.get(`/comercial/empresas/search`, {\n                    params: {\n                      search: query,\n                      limit: 50\n                    }\n                  });\n\n                  this.list_empresas = response.data.data || response.data;\n\n                  // Si hay una empresa pre-seleccionada que no está en los resultados, agrégala\n                  if (this.form.empresa_id && this.empresaEntity) {\n                    const exists = this.list_empresas.find(e => e.id === this.form.empresa_id);\n                    if (!exists) {\n                      this.list_empresas.unshift({\n                        id: this.form.empresa_id,\n                        razon_social: this.empresaEntity.razon_social\n                      });\n                    }\n                  }\n                } catch (error) {\n                  this.list_empresas = [];\n                } finally {\n                  this.loading = false;\n                }\n              }, 400);\n            },\n            handleFocus() {\n              if (!this.form.empresa_id && this.list_empresas.length === 0) {\n                this.getEmpresas('');\n              }\n            },\n            initForm() {\n                this.errors = {}\n                this.form = {\n                    id: null,\n                    empresa_id: null,\n                    nombres: null,\n                    apellidos: null,\n                    cargo: null,\n                    celular: null,\n                    email: null,\n                    telefono:null,\n                    emails: [],\n                    estado: 1,\n                    origen: null,\n                    tipo_contacto: null,\n                    fecha_cumpleanos: null,\n                    direccion: null\n                }\n                this.originalForm = JSON.stringify(this.form)\n            },\n            async submit() {\n                this.loading_submit = true\n                this.$http.post(`/${this.resource}`, this.form)\n                    .then(response => {\n                        if (response.data.success) {\n                            this.$message.success(response.data.message)\n                            if (this.context === 'empresas') {\n                              this.$emit('contactSaved', this.empresaId || this.form.empresa_id);\n                            } else {\n                              this.$eventHub.$emit('reloadData');\n                            }\n                            this.close()\n                        } else {\n                            this.$message.error(response.data.message)\n                        }\n                    })\n                    .catch(error => {\n                        if (error.response.status === 422) {\n                            this.errors = error.response.data\n                        }\n                    })\n                    .then(() => {\n                        this.loading_submit = false\n                    })\n\n            },\n\n            close() {\n              this.$emit('update:showDialog', false)\n              this.$emit('update:recordId', null)\n              this.initForm()\n              this.isInitialized = false\n            },\n\n            clickAddEmails() {\n              this.form.emails.push({\n                'id': null,\n                'telefono': null,\n                'email': null,\n              });\n            },\n            clickRemoveEmails(index) {\n              this.form.emails.splice(index, 1);\n            },\n        }\n    }\n</script>\n<style>\n.avatar-uploader {\n    width: 178px;\n    height: 178px;\n}\n.avatar {\n    width: 100%;\n    height: 100%;\n    object-fit: cover;\n}\n.avatar-uploader-icon {\n    font-size: 28px;\n    color: #8c8c8c;\n    line-height: 178px;\n    text-align: center;\n    max-width: 178px;\n}\n</style>\n"],"sourceRoot":""}]);
