iv class=\"right-wrapper pull-right\">\n                <button\n                    class=\"btn btn-custom btn-sm  mt-2 mr-2\"\n                    type=\"button\"\n                    @click.prevent=\"clickCreate()\"\n                >\n                    <i class=\"fa fa-plus-circle\"></i> Nuevo\n                </button>\n            </div>\n        </div>\n        <div class=\"card tab-content-default row-new mb-0\">\n            <!-- <div class=\"card-header bg-info\">\n                <h3 class=\"my-0\">Listado de {{ title }}</h3>\n            </div> -->\n            <div class=\"card-body\">\n                <data-table :resource=\"resource\">\n                    <tr slot=\"heading\">\n                        <!-- <th>#</th> -->\n                        <th>Nombre</th>\n                        <th class=\"text-left\">Tipo de documento</th>\n                        <th class=\"text-right\">Número</th>\n                        <th class=\"text-left\">Fecha admisión</th>\n                        <th>Cargo</th>\n                        <th class=\"text-right\">Acciones</th>\n                    </tr>\n                    <tr slot-scope=\"{ index, row }\">\n                        <!-- <td>{{ index }}</td> -->\n                        <td>{{ row.name }}</td>\n                        <td class=\"text-left\">{{ row.document_type }}</td>\n                        <td class=\"text-right\">{{ row.number }}</td>\n                        <td class=\"text-left\">\n                            {{ formatDate(row.admission_date) }}\n                        </td>\n                        <td>{{ row.occupation }}</td>\n                        <td class=\"text-right\">\n                            <div class=\"dropdown\">\n                                <button\n                                    class=\"btn btn-default btn-sm btn-dropdown-toggle\"\n                                    type=\"button\"\n                                    id=\"dropdownMenuButton\"\n                                    data-toggle=\"dropdown\"\n                                    aria-haspopup=\"true\"\n                                    aria-expanded=\"false\"\n                                >\n                                    <i class=\"fas fa-ellipsis-v\"></i>\n                                    <i class=\"fas fa-ellipsis-h\" style=\"display: none;\"></i>\n                                </button>\n                                <div\n                                    class=\"dropdown-menu\"\n                                    aria-labelledby=\"dropdownMenuButton\"\n                                >\n                                    <div>\n                                        <button\n                                            class=\"dropdown-item\"\n                                            @click.prevent=\"clickCreate(row.id)\"\n                                        >\n                                            Editar\n                                        </button>\n                                    </div>\n                                    <button\n                                        class=\"dropdown-item\"\n                                        @click.prevent=\"clickDelete(row.id)\"\n                                    >\n                                        Eliminar\n                                    </button>\n                                </div>\n                            </div>\n                        </td>\n                    </tr>\n                </data-table>\n            </div>\n\n            <worker-form\n                :recordId=\"recordId\"\n                :showDialog.sync=\"showDialog\"\n            ></worker-form>\n        </div>\n    </div>\n</template>\n<style>\n@media only screen and (max-width: 485px) {\n    .filter-container {\n        margin-top: 0px;\n        & .btn-filter-content,\n        .btn-container-mobile {\n            display: flex;\n            align-items: center;\n            justify-content: start;\n        }\n    }\n}\n</style>\n<script>\nimport WorkerForm from \"./form.vue\";\nimport DataTable from \"@components/DataTable.vue\";\nimport { deletable } from \"@mixins/deletable\";\n\nexport default {\n    mixins: [deletable],\n    components: { WorkerForm, DataTable },\n    data() {\n        return {\n            title: null,\n            showDialog: false,\n            resource: \"workers\",\n            recordId: null\n        };\n    },\n    created() {\n        this.title = \"Empleados\";\n    },\n    methods: {\n        formatDate(date) {\n            if (!date) return null;\n            const parsedDate = moment(date);\n            return parsedDate.isValid()\n                ? parsedDate.format(\"DD-MM-YYYY\")\n                : null;\n        },\n        clickCreate(recordId = null) {\n            this.recordId = recordId;\n            this.showDialog = true;\n        },\n        clickDelete(id) {\n            this.destroy(`/${this.resource}/${id}`).then(() =>\n                this.$eventHub.$emit(\"reloadData\")\n            );\n        }\n    }\n};\n</script>\n"],"sourceRoot":""}]);
